// 2 Паралипоменон — Біблія, переклад Патріарха Філарета. Згенеровано scripts/build_bible.py, не правте вручну.
import type { BChap } from '../types';
const C: BChap[] = [{"v":["І утвердився Соломон, син Давидів, у царстві своєму; і Господь Бог його був з ним, і підніс його високо.","І наказав Соломон зібратися всьому Ізраїлю: тисячоначальникам і стоначальникам, і суддям, і всім начальникам у всьому Ізраїлі — главам поколінь.","І пішли Соломон і все зібрання з ним на висоту, що в Гаваоні, тому що там була Божа скинія зібрання, яку спорудив Мойсей, раб Господній, у пустелі.","Ковчег Божий приніс Давид з Кириаф-Іарима на місце, яке приготував для нього Давид, спорудивши для нього скинію в Єрусалимі.","А мідний жертовник, який зробив Веселеїл, син Урія, сина Орового, залишався там, перед скинією Господньою, і знайшов його Соломон із зібранням.","І там перед лицем Господа, на мідному жертовнику, що перед скинією зібрання, підніс Соломон тисячу всепалень.","У ту ніч явився Бог Соломону і сказав йому: проси, що Мені дати тобі.","І сказав Соломон Богу: Ти сотворив Давиду, батькові моєму, велику милість і поставив мене царем замість нього.","Нехай же сповниться, Господи Боже, слово Твоє до Давида, батька мого. Окільки Ти поставив мене царем над народом численним, як порох земний,","то нині дай мені премудрість і знання, щоб я умів виходити перед народом цим і входити, бо хто може управляти цим народом Твоїм великим?","І сказав Бог Соломону: за те, що це було на серці твоєму, і ти не просив багатства, маєтків і слави і душ ворогів твоїх, і також не просив ти багатьох днів, а просив собі премудрости і знання, щоб управляти народом Моїм, над яким Я поставив тебе царем,","премудрість і знання даються тобі, а багатство і маєтки і славу Я дам тобі такі, подібних до яких не бувало в царів раніше тебе і не буде після тебе.","І прийшов Соломон з висоти, що в Гаваоні, від скинії зібрання, в Єрусалим і царював над Ізраїлем.","І набрав Соломон колісниць і вершників; і було в нього тисяча чотириста колісниць і дванадцять тисяч вершників; і він розмістив їх у колісничних містах і при царі в Єрусалимі.","І зробив цар срібло і золото в Єрусалимі рівноцінним простому каменю, а кедри, за безліччю їх, зробив рівноцінними сикоморам, що на низьких місцях.","Коней Соломону приводили з Єгипту і з Куви; купці царські з Куви одержували їх за гроші.","Колісниці одержували і доставляли з Єгипту кожну за шістсот сиклів срібла, а коня за сто п’ятдесят. У такий же спосіб вони руками своїми доставляли це всім царям хеттейським і царям арамейським."],"x":{"1":"10.2.12","3":"10.3.4|12.16.39|1.40.18","4":"9.6.17","5":"1.31.2|1.38.1","7":"10.3.5","8":"12.28.5","9":"10.3.8|29.9.7","10":"10.3.12|29.7.7|3.27.17","11":"10.3.11-12","12":"10.3.13|13.9.22","14":"10.10.26","15":"10.10.27","16":"10.10.28","17":"10.10.29"}},{"v":["І поклав Соломон побудувати дім імені Господньому і дім царський для себе.","І відрахував Соломон сімдесят тисяч носіїв і вісімдесят тисяч каменотесів у горах, і наглядачів над ними три тисячі шістсот.","І послав Соломон до Хирама, царя Тирського, сказати: як робив ти з Давидом, батьком моїм, і надсилав йому кедри на побудову дому для нього, щоб жити в ньому, так роби і зі мною.","Ось я будую дім імені Господа Бога мого, для присвяти Йому, щоб запалювати перед Ним запашне куріння, приносити постійно хліби предкладення і возносити там всепалення ранком і ввечері в суботи, і в новомісяччя, й у свята Господа Бога нашого, що назавжди заповідано Ізраїлю.","І дім, який я будую, великий, тому що великий Бог наш, вище за всіх богів.","І чи вистачить у кого сили побудувати Йому дім, коли небо і небеса небес не вміщають Його? І хто я, щоб міг побудувати Йому дім? Хіба тільки для куріння перед лицем Його.","Отже, пришли мені чоловіка, який уміє робити вироби із золота, і зі срібла, і з міді, і з заліза, і з пряжі пурпурового, багряного і яхонтового кольору, і який знає як вирізувати і виконувати різьблену роботу, разом з художниками, які є в мене в Юдеї й в Єрусалимі, яких приготував Давид, батько мій.","І пришли мені кедрових дерев, і кипарису і певгового дерева з Ливану, бо я знаю, що раби твої вміють рубати дерева ливанські. І ось раби мої підуть з рабами твоїми,","щоб приготувати мені багато дерев, тому що дім, який я будую, великий і дивний.","І ось дереворубам, що рубають дерева, рабам твоїм, я даю для їжі: пшениці двадцять тисяч ко́рів, і ячменю двадцять тисяч ко́рів, і вина двадцять тисяч батів, і оливкової олії двадцять тисяч батів.","І відповів Хирам, цар Тирський, листом, який надіслав до Соломона: з любови до народу Свого Господь поставив тебе царем над ним.","І ще сказав Хирам: благословенний Господь Бог Ізраїлів, що створив небо і землю, що дав царю Давиду сина мудрого, який має сенс і розум, що має намір будувати дім Господу і дім царський для себе.","Отже, я посилаю [тобі] чоловіка розумного, що має знання, Хирам-Авия,","сина однієї жінки з дочок Данових, — а батько його тирянин, — який уміє робити вироби з золота і зі срібла, з міді, із заліза, з каменів і з дерев, з пряжі пурпурового, яхонтового кольору, і з висону, і з багряниці, і вирізувати всяке різьблення, і виконувати все, що буде доручено йому разом з художниками твоїми і з художниками господаря мого Давида, батька твого.","А пшеницю і ячмінь, оливкову олію і вино, про які ти говорив, господарю мій, пошли рабам твоїм.","Ми ж нарубаємо дерев з Ливану, скільки потрібно тобі, і приженемо їх плотами морем у Яфу, а ти відвезеш їх в Єрусалим.","І порахував Соломон усіх прибульців, які були тоді в землі Ізраїлевій, після переліку їх, зробленого Давидом, батьком його, — і знайшлося їх сто п’ятдесят три тисячі шістсот.","І зробив він з них сімдесят тисяч носіїв і вісімдесят тисяч каменотесів у горах і три тисячі шістсот наглядачів, щоб вони спонукували народ до роботи."],"x":{"2":"10.5.15","3":"10.5.2","5":"4.10.17|25.88.7","6":"10.8.27|31.66.1|32.23.24","8":"10.10.12","9":"10.5.6","10":"10.5.11","12":"10.5.7","13":"10.7.13","14":"1.31.4|10.7.14","17":"12.22.2","18":"10.5.15"}},{"v":["І почав Соломон будувати дім Господній у Єрусалимі на горі Моріа, яка вказана була Давиду, батькові його, на місці, яке приготував Давид, на току Орни ієвусеянина.","Почав же він будувати у другий день другого місяця, у четвертий рік царювання свого.","І ось основа, покладена Соломоном при будівництві дому Божого: довжина його шістдесят ліктів, за попередньою міркою, а ширина двадцять ліктів;","і притвор, який перед домом, довжиною за шириною дому в двадцять ліктів, а висотою у сто двадцять. І обклав його всередині чистим золотом.","Дім же головний обшив деревом кипарисовим і обклав його кращим золотом, і зробив на ньому пальми і ланцюжки.","І обклав дім дорогими каменями для краси; золото ж було золото парваїмське.","І покрив золотом дім, колоди, пороги і стіни його, [і вікна] і двері його, і вирізав на стінах херувимів.","І зробив Святе Святих: довжина його за шириною дому у двадцять ліктів, і ширина його у двадцять ліктів; і покрив його кращим золотом на шістсот талантів.","У цвяхах ваги до п’ятдесяти сиклів золота [у кожному цвяху]. Світлиці також покрив золотом.","І зробив він у Святому Святих двох херувимів різьбленої роботи і покрив їх золотом.","Крила херувимів були довжиною у двадцять ліктів. Одне крило в п’ять ліктів торкалося стіни дому, а друге крило теж у п’ять ліктів сходилося з крилом другого херувима;","так само і крило другого херувима в п’ять ліктів торкалося стіни дому, а друге крило в п’ять ліктів сходилося з крилом другого херувима.","Крила цих херувимів були розпростерті на двадцять ліктів; і вони стояли на ногах своїх, лицями своїми до храму.","І зробив завісу з яхонтової, пурпурової і багряної тканини і з висону і зобразив на ній херувимів.","І зробив перед храмом два стовпи, довжиною по тридцять п’ять ліктів, і капітелі на верху кожного в п’ять ліктів.","І зробив ланцюжки, як у святилищі, і поклав на верху стовпів, і зробив сто ґранатових яблук і поклав на ланцюжки.","І поставив стовпи перед храмом, один з правого боку, другий з лівого, і дав ім’я правому Іахин, а лівому ім’я Воаз."],"x":{"1":"10.6.1|12.21.18|9.24.18","3":"10.6.2","4":"10.6.3","5":"10.6.15:21","6":"10.9.28","8":"10.6.16","10":"1.25.18|10.6.23","11":"10.6.24","13":"1.25.20","14":"1.26.1:31","15":"11.25.13|32.52.17","16":"10.7.17","17":"10.7.21"}},{"v":["І зробив мідний жертовник: двадцять ліктів довжина його і двадцять ліктів ширина його і десять ліктів висота його.","І зробив море відлите, — від краю його до краю його десять ліктів, — усе кругле, висотою в п’ять ліктів; і шнурок у тридцять ліктів обіймав його навколо;","і відлиті подоби волів стояли під ним навколо з усіх боків; на десять ліктів оточували навколо море два ряди волів, вилитих одним литтям з ним.","Стояло воно на дванадцяти волах: три дивилися на північ і три дивилися на захід, і три дивилися на південь, і три дивилися на схід, — і море на них зверху; зади ж їхні були звернені всередину під нього.","Завтовшки воно було з долоню; і краї його, зроблені, як краї чаші, були схожі на лілею, яка розквітла. Воно вміщало до трьох тисяч батів.","І зробив десять умивальниць, і поставив п’ять праворуч і п’ять ліворуч, щоб омивати у них, — те, що готується до всепалення омивали в них; море ж — для священиків, щоб вони омивались у ньому.","І зробив десять золотих світильників, як їм належало бути, і поставив у храмі, п’ять праворуч і п’ять ліворуч.","І зробив десять столів і поставив у храмі, п’ять праворуч і п’ять ліворуч, і зробив сто золотих чаш.","І зробив священичий двір і великий двір і двері до двору, і вереї їх обклав міддю.","Море поставив з правого боку, на південний схід.","І зробив Хирам тази, і лопатки, і чаші [і кадильниці, і всі жертовні сосуди]. І закінчив Хирам роботу, яку виконував для царя Соломона в домі Божому;","два стовпи і два опоясання вінців на верху стовпів, і дві сітки для покриття двох опоясань вінців, що на верху стовпів,","і чотириста ґранатових яблук на двох сітках, два ряди ґранатових яблук для кожної сітки, для покриття двох опоясань вінців, що на стовпах.","І підстави зробив він, і умивальниці зробив на підставах;","одне море, і дванадцять волів під ним,","і тази, і лопатки, і виделки, і все приладдя їх зробив Хирам-Авий царю Соломону для дому Господнього з полірованої міді.","В околиці Йордану відливав їх цар, у глинистій землі, між Сокхофом і Цередою.","І зробив Соломон усі ці речі у величезній кількості, так що не знали ваги міді.","Також зробив Соломон усі речі для дому Божого і золотий жертовник, і столи, на яких хліби предкладення,","і світильники і лампади їх, щоб запалювати їх за уставом перед давиром, з чистого золота;","і квіти, і лампади, і щипці з золота, з найчистішого золота,","і ножі, і кропильниці, і чаші, і лотки з найчистішого золота, і двері храму, — його внутрішні двері у Святе Святих, і двері храму у святилище, — з золота."],"x":{"1":"1.27.1|10.8.64","2":"10.7.23","4":"10.7.25","5":"10.7.26","6":"10.7.38","7":"10.7.49|12.28.15","8":"12.28.16","11":"10.7.40:45","12":"10.7.15|13.3.15-16","14":"10.7.27","17":"10.7.46","18":"10.7.47","19":"10.7.48","20":"10.7.49","22":"10.6.31"}},{"v":["І закінчилася вся робота, яку виконував Соломон для дому Господнього. І приніс Соломон присвячене Давидом, батьком його, і срібло і золото і всі речі і віддав у скарбниці дому Божого.","Тоді зібрав Соломон старійшин Ізраїлевих і всіх глав колін, начальників поколінь синів Ізраїлевих, в Єрусалим, для перенесення ковчега завіту Господнього з міста Давидового, тобто із Сиона.","І зібралися до царя всі ізраїльтяни на свято, у сьомий місяць.","І прийшли усі старійшини Ізраїлеві. Левити взяли ковчег","і понесли ковчег і скинію зібрання і всі речі священні, які в скинії, — понесли їх священики і левити.","Цар же Соломон і вся громада Ізраїлева, яка зібралася до нього перед ковчегом, приносили жертви з овець і волів, яких неможливо перелічити і визначити, через їхню безліч.","І принесли священики ковчег завіту Господнього на місце його, у давир храму — у Святе Святих, під крила херувимів.","І херувими розпростирали крила над місцем ковчега, і покривали херувими ковчег і жердини його зверху.","І висунулися жердини, так що головки жердин ковчега видні були перед давиром, але не висовувалися назовні, і вони там до цього дня.","Не було в ковчезі нічого, крім двох скрижалей, які поклав Мойсей на Хориві, коли Господь уклав завіт із синами Ізраїлевими, після виходу їх з Єгипту.","Коли священики вийшли зі святилища, бо усі священики, що знаходилися там, освятилися без різниці відділів;","і левити співці, — усі вони, тобто Асаф, Еман, Ідифун і сини їхні, і брати їхні, — одягнені у висон, з кимвалами і з псалтирями і цитрами стояли на східному боці жертовника, і з ними сто двадцять священиків, ті, що сурмили трубами,","і були, як один, які сурмили і співали, видаючи один голос на хваління і славослів’я Господа; і коли загримів звук труб і кимвалів і музичних інструментів, і хвалили Господа, бо Він благий, бо повік милість Його; тоді дім, дім Господній, наповнила хмара, і","не могли священики стояти на служінні через хмару, бо слава Господня наповнила дім Божий."],"x":{"1":"10.7.51","2":"10.8.1","3":"10.8.2:65","4":"3.4.15|12.15.2","6":"10.8.5","7":"10.8.6","9":"10.8.8","10":"1.25.16:21|10.8.9|75.9.4","11":"10.8.10","12":"12.25.1","13":"14.3.11|25.135.1|33.3.22","14":"10.8.11"}},{"v":["Тоді сказав Соломон: Господь сказав, що Він благоволить жити в мо́році,","а я побудував дім і житло Тобі, [Святий,] місце для вічного Твого перебування.","І обернувся цар лицем своїм і благословив усе зібрання ізраїльтян, — все зібрання ізраїльтян стояло, —","і сказав: благословенний Господь Бог Ізраїлів, Який, що́ сказав устами Своїми Давиду, батькові моєму, виконав нині рукою Своєю! Він говорив:","«з того дня, як Я вивів народ Мій із землі Єгипетської, Я не обрав міста в жодному з колін Ізраїлевих для побудови дому; в якому перебувало б ім’я Моє, і не обрав чоловіка, який був би правителем народу Мого Ізраїля,","але обрав Єрусалим, щоб там перебувало ім’я Моє, і обрав Давида, щоб він був над народом Моїм Ізраїлем».","І було на серці у Давида, батька мого, побудувати дім імені Господа, Бога Ізраїлевого.","Але Господь сказав Давиду, батькові моєму: «у тебе є на серці побудувати храм імені Моєму; добре, що це на серці в тебе.","Однак не ти побудуєш храму, а син твій, який вийде із стегон твоїх, — він побудує храм імені Моєму».","І виконав Господь слово Своє, яке вирік: я вступив на місці Давида, батька мого, і сів на престолі Ізраїлевім, як сказав Господь, і побудував дім імені Господа Бога Ізраїлевого.","І я поставив там ковчег, в якому завіт Господа, укладений Ним із синами Ізраїлевими.","І став Соломон біля жертовника Господнього попереду всього зібрання ізраїльтян, і підняв руки свої, —","бо Соломон зробив мідний амвон завдовжки у п’ять ліктів і шириною у п’ять ліктів, а висотою в три лікті, і поставив його посеред двору; і став на ньому, і схилив коліна перед усім зібранням ізраїльтян, і підняв руки свої до неба, —","і сказав: Господи Боже Ізраїлів! Нема Бога, подібного до Тебе, ні на небі, ні на землі. Ти зберігаєш завіт і милість до рабів Твоїх, що ходять перед Тобою всім серцем своїм:","Ти виконав рабу Твоєму Давиду, батькові моєму, те, що Ти говорив йому; що прорік Ти устами Твоїми, те в день цей виконав рукою Твоєю.","І нині, Господи Боже Ізраїлів! виконай рабу Твоєму Давиду, батькові моєму, те, що Ти сказав йому, говорячи: не припиниться у тебе [муж,] який сидить перед лицем Моїм на престолі Ізраїлевім, якщо тільки сини твої будуть пильнувати за шляхами своїми, ходячи за законом Моїм так, як ти ходив переді Мною.","І нині, Господи Боже Ізраїлів! нехай буде вірним слово Твоє, яке Ти прорік рабу Твоєму Давиду.","Воістину, чи Богу жити з людьми на землі? Якщо небо і небеса небес не вміщають Тебе, тим менш храм цей, який побудував я.","Але зглянься на молитву раба Твого і на прохання його, Господи Боже мій! почуй взивання і молитву, якою раб Твій молиться перед Тобою.","Нехай будуть очі Твої відкриті на храм цей вдень і вночі, на місце, де Ти обіцяв покласти ім’я Твоє, щоб чути молитву, якою раб Твій буде молитися на місці цьому.","Почуй моління раба Твого і народу Твого Ізраїля, якими вони будуть молитися на місці цьому; почуй з місця оселі Твоєї, з небес, почуй і помилуй!","Коли хто згрішить проти ближнього свого, і будуть вимагати від нього клятви, щоб він поклявся, і буде звершуватися клятва перед жертовником Твоїм у храмі цьому,","тоді Ти почуй з неба і вчини суд над рабами Твоїми, воздай винному, поклавши вчинок його на голову його, і виправдай правого, воздавши йому за правдою його.","Коли вражений буде народ Твій Ізраїль ворогом за те, що згрішив перед Тобою, і вони звернуться до Тебе, і сповідають ім’я Твоє, і будуть просити і молитися перед Тобою в храмі цьому,","тоді Ти почуй з неба, і прости гріх народу Твого Ізраїля, і поверни їх у землю, яку Ти дав їм і батькам їхнім.","Коли закриється небо і не буде дощу за те, що вони згрішили перед Тобою, і будуть молитися на місці цьому, і сповідають ім’я Твоє, і навернуться від гріха свого, тому що Ти смирив їх,","тоді Ти почуй з неба і прости гріх рабів Твоїх і народу Твого Ізраїля, показавши їм добрий шлях, яким іти їм, і пошли дощ на землю Твою, яку Ти дав народу Твоєму в спадщину.","Чи голод буде на землі, чи буде моровиця, чи буде вітер палючий або іржа, сарана або черва, чи будуть тіснити його вороги його на землі володінь його, чи буде яка біда, яка хвороба,","усяку молитву, усяке прохання, яке буде від якої-небудь людини або від усього народу Твого Ізраїля, коли вони відчують кожен біду свою і горе своє і простягнуть руки свої до храму цього,","Ти почуй з неба — місця оселі Твоєї, і прости, і воздай кожному за всіма шляхами його, як Ти знаєш серце його, — бо Ти один знаєш серце синів людських, —","щоб вони боялися Тебе і ходили шляхами Твоїми в усі дні, доки живуть на землі, яку Ти дав батькам нашим.","Навіть і іноплемінник, який не від народу Твого Ізраїля, коли він прийде з землі далекої заради імені Твого великого і руки Твоєї могутньої і сили Твоєї простягнутої, і прийде і буде молитися біля храму цього,","Ти почуй з неба, з місця оселі Твоєї, і зроби все, про що буде волати до Тебе іноплемінник, щоб усі народи землі узнали ім’я Твоє, і щоб боялися Тебе, як народ Твій Ізраїль, і знали, що Твоїм ім’ям називається дім цей, який побудував я.","Коли вийде народ Твій на війну проти ворогів своїх шляхом, яким Ти пошлеш його, і буде молитися Тобі, звернувшись до міста цього, яке обрав Ти, і до храму, який я побудував імені Твоєму,","тоді почуй з неба молитву їх і прохання їх і зроби, що потрібно для них.","Коли вони згрішать перед Тобою, — тому що немає людини, яка не згрішила б, — і Ти прогніваєшся на них, і віддаси їх ворогові, і відведуть їх ті, що полонили їх, у землю далеку або близьку,","і коли вони в землі, в яку будуть полонені, ввійдуть у себе і навернуться і будуть молитися Тобі в землі полону свого, говорячи: ми згрішили, зробили беззаконня, ми винні,","і звернуться до Тебе всім серцем своїм і всією душею своєю в землі полону свого, куди відведуть їх у полон, і будуть молитися, звернувшись до землі своєї, яку Ти дав батькам їхнім, і до міста, яке обрав Ти, і до храму, який я побудував імені Твоєму, —","тоді почуй з неба, з місця оселі Твоєї, молитву їх і прохання їх, і зроби, що потрібно для них, і прости народу Твоєму, в чому він згрішив перед Тобою.","Боже мій! нехай будуть очі Твої відкриті і вуха Твої уважні до молитви на місці цьому.","І нині, Господи Боже, стань на місце спокою Твого, Ти і ковчег могутности Твоєї. Священики Твої, Господи Боже, нехай одягнуться у спасіння, і преподобні Твої нехай насолодяться благами.","Господи Боже! не відверни лиця помазаника Твого, пом’яни милости до Давида, раба Твого."],"x":{"1":"10.8.12","3":"9.6.18|10.8.14:55","4":"10.8.15","5":"9.7.6|10.8.16","7":"9.7.2|10.8.17|12.17.1","9":"10.8.19|29.9.8","10":"10.8.20","12":"10.8.22|14.9.5","13":"10.8.22|22.2.8|66.3.14","14":"22.2.10|10.8.23","16":"10.8.25|9.7.16","17":"10.8.17","18":"10.8.27|13.2.6|31.66.1","20":"10.8.29|4.12.5|4.31.11","21":"10.8.30","22":"10.8.31|1.22.11","23":"10.8.32","24":"10.8.33-34|4.28.25","26":"2.26.19|4.11.17|10.8.35","28":"13.20.9","32":"10.8.41|31.55.5-6","36":"10.8.46|26.20.9|27.7.20|16.8.35|58.1.8","37":"37.9.13|3.14.40","38":"8.7.6|10.8.47-48","39":"25.33.16","41":"3.10.36|25.131.8-9","42":"9.7.13:15"}},{"v":["Коли закінчив Соломон молитву, зійшов вогонь з неба і поглинув всепалення і жертви, і слава Господня наповнила дім.","І не могли священики ввійти в дім Господній, тому що слава Господня наповнила дім Господній.","І всі сини Ізраїлеві, бачачи, як зійшов вогонь і слава Господня на дім, упали лицем на землю, на поміст, і поклонилися, і славословили Господа, тому що Він благий, бо повік милість Його.","Цар же і весь народ стали приносити жертви перед лицем Господа.","І приніс цар Соломон у жертву двадцять дві тисячі волів і сто двадцять тисяч овець: так освятили дім Божий цар і весь народ.","Священики стояли на служінні своєму, і левити з музичними інструментами Господа, які зробив цар Давид для прославлення Господа, бо вічна милість Його, тому що Давид славословив через них; священики ж сурмили перед ним, і весь Ізраїль стояв.","Освятив Соломон і внутрішню частину двору, що перед домом Господнім: бо приніс там всепалення і жир мирних жертв, тому що жертовник мідний, зроблений Соломоном, не міг вміщувати всепалення і хлібного приношення, і жиру.","І зробив Соломон у той час семиденне свято, і весь Ізраїль з ним — зібрання дуже велике, що зійшлося від входу в Емаф до ріки єгипетської;","а в день восьмий зробили післясвято, тому що освячення жертовника звершували сім днів і свято сім днів.","І в двадцять третій день сьомого місяця цар відпустив у намети їхні народ, який радів і веселився в серці за благо, яке зробив Господь Давиду і Соломону й Ізраїлю, народові Своєму.","І закінчив Соломон дім Господній і дім царський; і все, що задумав Соломон у серці своєму зробити в домі Господньому й у домі своєму, зробив він успішно.","І явився Господь Соломону вночі і сказав йому: Я почув молитву твою й обрав Собі місце це в дім жертвоприношення.","Якщо Я закрию небо і не буде дощу, і якщо повелю сарані поїдати землю, або пошлю моровицю на народ Мій,","і смириться народ Мій, який називається ім’ям Моїм, і будуть молитися, і шукатимуть лиця Мого, і навернуться від злих шляхів своїх, то Я почую з неба і прощу гріхи їхні і зцілю землю їхню.","Нині очі Мої будуть відкриті і вуха Мої уважні до молитви на місці цьому.","І нині Я обрав і освятив дім цей, щоб ім’я Моє було там повіки; і очі Мої і серце Моє будуть там в усі дні.","І якщо ти будеш ходити перед лицем Моїм, як ходив Давид, батько твій, і будеш робити усе, що Я повелів тобі, і будеш зберігати устави Мої і закони Мої,","то утверджу престіл царства твого, як Я обіцяв Давиду, батькові твоєму, говорячи: не припиниться в тебе [муж,] що володіє Ізраїлем.","Якщо ж ви відступите і залишите устави Мої і заповіді Мої, які Я дав вам, і підете і станете служити богам іншим і поклонятися їм,","то Я знищу Ізраїля з лиця землі Моєї, яку Я дав їм, і храм цей, який Я освятив імені Моєму, відкину від імені Мого і зроблю його притчею і посміховиськом у всіх народів.","І щодо храму цього високого усякий, хто проходить мимо нього, жахнеться і скаже: за що зробив так Господь із землею цією і з храмом цим?","І скажуть: за те, що вони залишили Господа, Бога батьків своїх, Який вивів їх із землі Єгипетської, і приліпилися до богів інших, і поклонялися їм, і служили їм, — за те Він навів на них усю цю біду."],"x":{"1":"22.2.10","2":"10.8.11","3":"13.5.13|14.3.11","4":"10.8.62","5":"10.8.63","6":"12.16.5|3.10.10|30.50.18","7":"10.8.64","8":"10.8.65|3.13.22","9":"53.7.37|10.8.2:65","10":"10.8.66","11":"10.9.1","12":"4.12.5","14":"25.105.6|4.28.10|40.9.12","15":"13.6.40","16":"10.9.3","18":"9.7.12|10.9.5|12.17.12","19":"10.9.6","20":"4.4.26|5.23.16|32.7.15","21":"4.29.24|10.9.8|32.22.8"}},{"v":["Після закінчення двадцяти років, у які Соломон будував дім Господній і свій дім,","Соломон відбудував і міста, які дав Соломону Хирам, і оселив у них синів Ізраїлевих.","І пішов Соломон на Емаф-Сува і взяв його.","І побудував він Фадмор у пустелі, і всі міста для запасів, які заснував у Емафі.","Він оббудував Вефорон верхній і Вефорон нижній, міста укріплені, зі стінами, воротами і запорами,","і Ваалаф і всі міста для запасів, які були у Соломона, і всі міста для колісниць, і міста для кінноти, і все, що хотів Соломон побудувати в Єрусалимі і на Ливані й у всій землі володіння свого.","Весь народ, який залишився від хеттеїв, і аморреїв, і ферезеїв, і евеїв і ієвусеїв, які були не із синів Ізраїлевих, —","дітей їхніх, що залишилися після них на землі, яких не знищили сини Ізраїлеві, — зробив Соломон оброчними до цього дня.","Синів же Ізраїлевих не робив Соломон робітниками у справах своїх, але вони були воїнами, і начальниками охоронців його, і вождями колісниць його і вершників його.","І було головних приставників у царя Соломона, які керували народом, двісті п’ятдесят.","А дочку фараонову перевів Соломон з міста Давидового в дім, який побудував для неї, тому що, говорив він, не повинна жити жінка у мене в домі Давида, царя Ізраїлевого, бо святий він, тому що ввійшов у нього ковчег Господній.","Тоді став приносити Соломон всепалення Господу на жертовнику Господньому, який він спорудив перед притвором,","щоб за уставом кожного дня приносити всепалення, за заповіддю Мойсея, у суботи, і в новомісяччя, й у свята тричі на рік: у свято опрісноків, і у свято седмиць, у свято кущів.","І встановив він, за розпорядженням Давида, батька свого, черги священиків за службою їх і левитів за сторо́жами їх, щоб вони славословили і служили при священиках за уставом кожного дня, і воротарів за чергами їхніми, до кожних воріт, тому що такий був заповіт Давида, чоловіка Божого.","І не відступали від повелінь царя про священиків і левитів ні в чому, ні стосовно скарбів.","Так влаштована була вся справа Соломонова від дня заснування дому Господнього до остаточного закінчення його — дому Господнього.","Тоді пішов Соломон в Еціон-Гавер і в Елаф, що на березі моря, у землі Ідумейській.","І надіслав йому Хирам через слуг своїх кораблі і рабів, які знають море, і вирушили вони зі слугами Соломоновими в Офир, і здобули звідти чотириста п’ятдесят талантів золота, і привезли цареві Соломону."],"x":{"1":"10.9.10","2":"10.9.11-12","3":"3.13.22","5":"10.9.17","6":"10.9.18-19","7":"10.9.20","8":"5.16.10|6.1.28|10.9.21","10":"10.9.23","11":"10.9.24","13":"1.23.14|2.24.8|10.9.25","14":"12.24.1","17":"10.9.26-27"}},{"v":["Цариця Савська, почувши про славу Соломона, прийшла випробувати Соломона загадками в Єрусалим, з дуже великим багатством, і з верблюдами, нав’юченими пахощами і безліччю золота і дорогоцінних каменів. І прийшла до Соломона і розмовляла з ним про все, що було на серці у неї.","І пояснив їй Соломон усі слова її, і не знайшлося нічого незнайомого Соломону, чого він не пояснив би їй.","І побачила цариця Савська мудрість Соломона і дім, який він побудував,","і їжу за столом його, і житло рабів його, і добропристойність службовців його й одяг їхній, і виночерпіїв його й одяг їхній, і хід, яким він ходив у дім Господній, — і була вона у захопленні.","І сказала цареві: правда те, що я чула в землі моїй про справи твої і про мудрість твою,","але я не вірила словам про них, доки не прийшла і не побачила очима своїми. І ось, мені і наполовину не сказано про безліч мудрости твоєї: ти перевершуєш поголос, який я чула.","Блаженні люди твої, і блаженні ці слуги твої, що завжди стоять перед тобою і чують мудрість твою!","Нехай буде благословенний Господь Бог твій, Який благозволив посадити тебе на престіл Свій царем у Господа Бога твого. З любови Бога твого до Ізраїля, щоб утвердити його навіки, Він поставив тебе царем над ним — чинити суд і правду.","І подарувала вона царю сто двадцять талантів золота і багато пахощів і коштовних каменів; і не бувало таких пахощів, які подарувала цариця Савська царю Соломону.","І слуги Хирамові і слуги Соломонові, які привезли золото з Офира, привезли і червоне дерево і коштовні камені.","І зробив цар з цього червоного дерева сходи до дому Господнього і до дому царського, і цитри і псалтирі для співців. І не бачено було подібного до цього раніше в землі Юдейській.","Цар же Соломон дав цариці Савській усе, чого вона бажала і чого вона просила, крім таких речей, які вона привезла цареві. І вона вирушила назад у землю свою, вона і слуги її.","Вага золота, що приходило до Соломона в один рік, була шістсот шістдесят шість талантів золота.","Поверх того, посли і купці приносили, і всі царі аравійські і начальники обласні приносили золото і срібло Соломону.","І зробив цар Соломон двісті великих щитів з кованого золота, — по шістсот сиклів кованого золота пішло на кожен щит, —","і триста щитів менших з кованого золота, — по триста сиклів золота пішло на кожен щит; і поставив їх цар у домі з ливанського дерева.","І зробив цар великий престіл зі слонової кістки й обклав його чистим золотом,","і шість сходинок до престолу і золоте підніжжя, до престолу прироблене, і підлокітники з обох боків місця сидіння, і двох левів, які стоять біля підлокітників,","і ще дванадцять левів, які стоять там на шести східцях, з обох боків Не бувало такого [престолу] у жодному царстві.","І весь посуд для пиття у царя Соломона був із золота, і всі сосуди в домі з ливанського дерева були із золота добірного; срібло в дні Соломона ставилося за ніщо,","бо кораблі царя ходили у Фарсис зі слугами Хирама, і на три роки раз поверталися кораблі з Фарсиса і привозили золото і срібло, слонову кістку і мавп і павичів.","І перевершив цар Соломон усіх царів землі багатством і мудрістю.","І всі царі землі прагнули бачити Соломона, щоб послухати мудрість його, яку вклав Бог у серце його.","І кожен з них підносив від себе в дарунок сосуди срібні і сосуди золоті й одяг, зброю і пахощі, коней і ослів, з року в рік.","І було в Соломона чотири тисячі стійл для коней і колісниць і дванадцять тисяч вершників; і він розмістив їх у містах колісничних і при цареві — в Єрусалимі;","і царював він над усіма царями, від ріки Євфрату до землі Филистимської і до меж Єгипту.","І зробив цар [золото і] срібло в Єрусалимі рівноцінним простому каменю, а кедри, за їх безліччю, зробив рівноцінними сикоморам, що на низьких місцях.","Коней приводили Соломону з Єгипту і з усіх земель.","Інші діяння Соломонові, перші й останні, описані в записах Нафана пророка і в пророцтві Ахиї силомлянина й у видіннях прозорливця Іоїля про Ієровоама, сина Наватового.","Царював же Соломон в Єрусалимі над усім Ізраїлем сорок років.","І спочив Соломон з батьками своїми, і поховали його в місті Давида, батька його. І став царем Ровоам, син його, замість нього."],"x":{"1":"10.10.1|50.12.42|52.11.31","2":"10.10.3","3":"10.10.4-5","5":"10.10.6","7":"10.10.8|50.13.16-17","8":"10.10.9|13.2.11","9":"10.10.10","10":"10.10.11","12":"10.10.13","13":"10.10.14","15":"10.10.16","17":"10.10.18","20":"10.10.21","21":"10.10.22","22":"10.10.23|13.1.12","23":"55.1.5","25":"10.4.26","26":"10.4.21","27":"10.10.27|13.1.15","29":"10.1.11","30":"10.11.42","31":"10.11.43"}},{"v":["І пішов Ровоам у Сихем, тому що в Сихем зійшлися всі ізраїльтяни, щоб поставити його царем.","Коли почув про це Ієровоам, син Наватів, — він знаходився в Єгипті, куди втік від царя Соломона, — то повернувся Ієровоам з Єгипту.","І послали і кликали його; і прийшов Ієровоам і весь Ізраїль, і говорили Ровоаму так:","батько твій наклав на нас тяжке ярмо; але ти полегши жорстоку роботу батька твого і тяжке ярмо, яке він поклав на нас, і ми будемо служити тобі.","І сказав їм Ровоам: через три дні прийдіть знову до мене. І розійшовся народ.","І радився цар Ровоам зі старійшинами, які стояли перед лицем Соломона, батька його, за життя його, і говорив: як ви порадите відповісти народу цьому?","Вони сказали йому: якщо ти [нині] будеш добрим до народу цього і догодиш їм і будеш говорити з ними ласкаво, то вони будуть тобі рабами в усі дні.","Але він залишив пораду старійшин, яку вони давали йому, і став радитися з людьми молодими, які виросли разом з ним, і які стояли перед лицем його;","і сказав їм: що ви порадите мені відповісти народу цьому, який говорив мені так: полегши ярмо, яке наклав на нас батько твій?","І говорили йому молоді люди, які виросли разом з ним, і сказали: так скажи народу, який говорив тобі: батько твій наклав на нас тяжке ярмо, а ти полегши нам, — так скажи їм: мізинець мій товщий за стегна батька мого.","Батько мій наклав на вас тяжке ярмо, а я збільшу ярмо ваше; батько мій карав вас бичами, а я [буду бити вас] скорпіонами.","І прийшов Ієровоам і весь народ до Ровоама на третій день, як наказав цар, сказавши: прийдіть до мене знову через три дні.","Тоді цар відповідав їм суворо, бо залишив цар Ровоам пораду старійшин, і говорив їм за порадою молодих людей так:","батько мій наклав на вас тяжке ярмо, а я збільшу його; батько мій карав вас бичами, а я [буду бити вас] скорпіонами.","І не послухав цар народу, тому що так було влаштовано від Бога, щоб виконати Господу слово Своє, яке вирік Він через Ахию силомлянина Ієровоаму, синові Наватовому.","Коли весь Ізраїль побачив, що не слухає його цар, то відповів народ цареві, говорячи: яка наша частка у Давиді? Немає нам частки у сині Ієссеєвому; по наметах своїх, Ізраїлю! Тепер знай свій дім, Давиде. І розійшлися всі ізраїльтяни по наметах своїх.","Тільки над синами Ізраїлевими, які жили в містах Іудиних, залишився царем Ровоам.","І послав цар Ровоам Адонирама, начальника над збиранням данини, і закидали його сини Ізраїлеві камінням, і він помер. Цар же Ровоам поспішив сісти на колісницю, щоб утекти в Єрусалим.","Так відокремилися ізраїльтяни від дому Давидового до цього дня."],"x":{"1":"10.12.1","2":"10.11.40","5":"10.12.5","8":"10.12.8","10":"10.12.10","12":"10.12.12|30.47.28","15":"10.11.29:31","16":"10.12.16|9.20.1","18":"10.4.6"}},{"v":["І прибув Ровоам в Єрусалим і скликав з дому Іудиного і Веніамінового сто вісімдесят тисяч добірних воїнів, щоб воювати з Ізраїлем і повернути царство Ровоаму.","І було слово Господнє до Самея, чоловіка Божого, і сказано:","скажи Ровоаму, синові Соломона, цареві Юдейському, і всьому Ізраїлю в коліні Іудиному і Веніаміновому:","так говорить Господь: не ходіть і не починайте війни з братами вашими; поверніться кожен у дім свій, бо Мною зроблено це. Вони послухалися слів Господніх і повернулися з походу проти Ієровоама.","Ровоам жив у Єрусалимі; він обніс міста в Юдеї стінами.","Він укріпив Вифлеєм і Ефам, і Фекою,","і Вефцур, і Сохо, і Одоллам,","і Геф, і Марешу, і Зиф,","і Адораїм, і Лахис, і Азеку,","і Цору, й Аїалон, і Хеврон, які знаходилися в коліні Іудиному і Веніаміновому.","І укріпив він фортеці ці, і влаштував у них начальників і сховища для хліба і деревної олії і вина.","І дав у кожне місто щити і списи й укріпив їх дуже сильно. І залишалися за ним Іуда і Веніамін.","І священики і левити, які були по всій землі Ізраїльській, зібралися до нього з усіх країв,","тому що залишили левити свої міські передмістя і свої володіння і прийшли в Юдею і в Єрусалим, оскільки відсторонив їх Ієровоам і сини його від священства Господнього","і поставив у себе жерців на висотах, і до козлів, і до тельців, яких він зробив.","А за ними і з усіх колін Ізраїлевих ті, що схилили серце своє, щоб шукати Господа Бога Ізраїлевого, приходили в Єрусалим, щоб приносити жертви Господу Богу батьків своїх.","І зміцнили вони царство Іудине і підтримували Ровоама, сина Соломонового, три роки, тому що ходили путями Давида і Соломона у ці три роки.","І взяв собі Ровоам за дружину Махалафу, дочку Ієромофа, сина Давидового, й Авихаїль, дочку Елиава, сина Ієссеєвого,","і вона народила йому синів: Ієуса і Шемарію і Загаму.","Після неї він узяв Мааху, дочку Авессалома, і вона народила йому Авию й Аттая, і Зизу і Шеломифа.","І любив Ровоам Мааху, дочку Авессалома, більше за усіх дружин і наложниць своїх, бо він мав вісімнадцять дружин і шістдесят наложниць і породив двадцять вісім синів і шістдесят дочок.","І поставив Ровоам Авию, сина Маахи, главою [і] князем над братами його, тому що хотів поставити його царем.","І діяв благорозсудливо, і розіслав усіх синів своїх по всіх землях Іуди і Веніаміна в усі укріплені міста, і дав їм утримання велике і знайшов багато дружин."],"x":{"1":"10.12.21","2":"10.12.22","4":"10.12.24|13.10.15","6":"0.35.19","14":"3.35.2|10.12.31","15":"10.12.31|13.13.9","17":"13.12.1","18":"8.16.6","20":"13.13.2","21":"10.15.2","22":"10.15.1"}},{"v":["Коли царство Ровоама утвердилося, і він зробився сильним, тоді він залишив закон Господній, і весь Ізраїль з ним.","На п’ятому році царювання Ровоама, Сусаким, цар Єгипетський, пішов на Єрусалим, — тому що вони відступили від Господа, —","з тисячею і двомастами колісниць і з шістдесятьма тисячами вершників; і не було числа народу, який прийшов з ним з Єгипту, ливиянам, сукхитам і ефіоплянам;","і взяв укріплені міста в Юдеї і прийшов до Єрусалима.","Тоді Самей пророк прийшов до Ровоама і князів Юдеї, які зібралися в Єрусалимі, рятуючись від Сусакима, і сказав їм: так говорить Господь: ви залишили Мене, за те і Я залишаю вас у руки Сусакиму.","І смирилися князі Ізраїлеві і цар і сказали: праведний Господь!","Коли побачив Господь, що вони смирилися, тоді було слово Господнє до Самея, і сказано: вони смирилися; не знищу їх і незабаром дам їм спасіння, і не проллється гнів Мій на Єрусалим рукою Сусакима;","однак же вони будуть слугами його, щоб знали, як це — служити Мені і служити царствам земним.","І прийшов Сусаким, цар Єгипетський, в Єрусалим і взяв скарби дому Господнього і скарби дому царського; усе взяв він, узяв і щити золоті, які зробив Соломон.","І зробив цар Ровоам, замість них, щити мідні, і віддав їх у руки начальників охоронців, які охороняли вхід дому царського.","Коли виходив цар у дім Господній, приходили охоронці і несли їх, і потім знову відносили їх у палату охоронців.","І коли він смирився, тоді відвернувся від нього гнів Господа і не згубив його до кінця; притому і в Юдеї було дещо добре.","І утвердився цар Ровоам в Єрусалимі і царював. Сорок один рік було Ровоаму, коли він став царем, і сімнадцять років царював у Єрусалимі, у місті, яке з усіх колін Ізраїлевих обрав Господь, щоб там перебувало ім’я Його. Ім’я матері його Наама, аммонитянка.","І робив він зло, тому що не налаштував серце своє для того, щоб шукати Господа.","Діяння Ровоамові, перші й останні, описані в записах Самея пророка й Адди прозорливця у родоводах. І були війни у Ровоама з Ієровоамом в усі дні.","І спочив Ровоам з батьками своїми і похований у місті Давидовому. І став царем Авия, син його, замість нього."],"x":{"1":"13.11.17|4.32.15|10.14.22","2":"10.14.25","5":"13.15.2","6":"37.9.14","7":"32.18.8","9":"10.10.16-17|13.9.15","10":"10.14.27","12":"10.14.13","13":"10.14.21","15":"10.14.29","16":"10.14.31"}},{"v":["У вісімнадцятий рік царювання Ієровоама став царем Авия над Іудою.","Три роки він царював у Єрусалимі; ім’я матері його Михая, дочка Урії, з Гиви. І була війна у Авиї з Ієровоамом.","І вивів Авия на війну військо, яке складалося з людей хоробрих, з чотирьохсот тисяч чоловік добірних; а Ієровоам виступив проти нього на війну з вісьмомастами тисячами чоловік, також добірних, хоробрих.","І став Авия на вершині гори Цемараїмської, однієї з гір Єфремових, і говорив: послухайте мене, Ієровоам і всі ізраїльтяни!","Чи не знаєте ви, що Господь Бог Ізраїлів дав царство Давиду над Ізраїлем повіки, йому і синам його, за завітом соли [вічним]?","Але повстав Ієровоам, син Наватів, раб Соломона, сина Давидового, і збунтувався проти господаря свого.","І зібралися навколо нього люди пусті, люди розбещені, й укріпилися проти Ровоама, сина Соломонового; Ровоам же був молодий і слабкий серцем і не встояв проти них.","І нині ви думаєте устояти проти царства Господнього в руці синів Давидових, тому що вас безліч, і у вас золоті тельці, яких Ієровоам зробив для вас богами.","Чи не ви вигнали священиків Господніх, синів Аарона, і левитів, і поставили в себе священиків, які з народів інших земель? Усякий, хто приходить для посвяти своєї з тельцем і з сімома баранами, стає у вас священиком лжебогів.","А у нас — Господь Бог наш; ми не залишали Його, і Господу служать священики, сини Ааронові, і левити при своїй справі.","І спалюють вони Господу всепалення щоранку і щовечора, і запашне куріння, і покладають рядами хліби на столі чистому, і запалюють золотий світильник і лампади його, щоб горіли щовечора, тому що ми дотримуємо встановлення Господа Бога нашого, а ви залишили Його.","І ось, у нас на чолі Бог, і священики Його, і труби гучні, щоб гриміти проти вас. Сини Ізраїлеві! не воюйте з Господом Богом батьків ваших, бо не матимете успіху.","Тим часом Ієровоам послав загін у засідку з тилу їм, так що сам він був попереду юдеїв, а засідка позаду них.","І оглянулися юдеї, і ось, битва проти них спереду і позаду; і воззвали вони до Господа, а священики засурмили трубами.","І викликнули юдеї. І коли викликнули юдеї, Бог уразив Ієровоама і всіх ізраїльтян перед лицем Авиї й Іуди.","І побігли сини Ізраїлеві від юдеїв, і віддав їх Бог у руки їхні.","І зробили їм Авия і народ його поразку сильну; і впало убитими в Ізраїля п’ятсот тисяч чоловік добірних.","І смирилися тоді сини Ізраїлеві, і були сильні сини Іудині, тому що уповали на Господа Бога батьків своїх.","І переслідував Авия Ієровоама і взяв у нього міста: Вефиль і залежні від нього міста, й Ієшану і залежні від неї міста, і Ефрон і залежні від нього міста.","І не входив уже в силу Ієровоам у дні Авиї. І вразив його Господь, і він помер.","Авия ж підсилився; і взяв собі чотирнадцять дружин і породив двадцять два сини і шістнадцять дочок.","Інші діяння Авиї і його вчинки і слова описані у сказанні пророка Адди."],"x":{"1":"10.15.1","2":"10.15.2|13.11.20","3":"10.15.7","6":"10.11.26","8":"10.12.28","9":"13.11.15|10.12.31","11":"1.27.21|2.8.35|2.24.4:6","12":"4.20.4|3.10.9|3.14.41","14":"3.10.9|5.6.3","18":"25.105.42","19":"10.12.29|53.11.54","22":"10.15.3"}},{"v":["І спочив Авия з батьками своїми, і поховали його в місті Давидовому. І став царем Аса, син його, замість нього. У дні його спочивала земля десять років.","І робив Аса добре й угодне в очах Господа Бога свого:","і відкинув він жертовники богів чужих і висоти, і розбив статуї, і вирубав посвячені дерева;","і повелів юдеям шукати Господа Бога батьків своїх, і виконувати закон [Його] і заповіді;","і скасував він у всіх містах Іудиних висоти і статуї сонця. І спокійним було при ньому царство.","І побудував він укріплені міста в Юдеї, бо спокійною була земля, і не було в нього війни в ті роки, оскільки Господь дав спокій йому.","І сказав він юдеям: побудуємо міста ці й обнесемо їх стінами з вежами, з воротами і запорами. Земля ще наша, тому що ми знайшли Господа Бога нашого: ми знайшли Його, — і Він дав нам спокій з усіх боків. І стали будувати, і мали успіх.","І було в Аси військової сили: озброєних щитом і списом з коліна Іудиного триста тисяч, і з коліна Веніамінового озброєних щитом і які стріляли з лука, двісті вісімдесят тисяч, людей хоробрих.","І вийшов на них Зарай ефіоплянин з військом у тисячу тисяч і з трьомастами колісниць і дійшов до Мареші.","І виступив Аса проти нього, і вишикувалися до битви на долині Цефата в Мареші.","І воззвав Аса до Господа Бога свого, і сказав: Господи! чи не в Твоїй силі допомогти сильному або безсилому? допоможи ж нам, Господи Боже наш: тому що ми на Тебе уповаємо і в ім’я Твоє вийшли ми проти безлічі цієї. Господи! Ти Бог наш: нехай не переможе Тебе людина.","І вразив Господь ефіоплян перед лицем Аси і перед лицем Іуди, і побігли ефіопляни.","І переслідував їх Аса і народ, який був з ним, до Герара, і впали ефіопляни, так що в них нікого не залишилося в живих, тому що вони вражені були перед Господом і перед воїнством Його. І набрали здобичі безліч.","І зруйнували всі міста навколо Герара, тому що напав на них жах від Господа; і розграбували всі міста і винесли з них дуже багато здобичі.","Також і пастуші курені зруйнували і погнали безліч стад дрібної худоби і верблюдів і повернулися в Єрусалим."],"x":{"1":"10.15.8","2":"10.15.11","3":"10.15.12","9":"13.16.8","11":"8.14.6","12":"13.13.15","14":"13.17.10"}},{"v":["Тоді на Азарію, сина Одедового, зійшов Дух Божий,","і вийшов він назустріч Асі і сказав йому: послухайте мене, Асо і весь Іуда і Веніамін: Господь з вами, коли ви з Ним; і якщо будете шукати Його, Він буде знайдений вами; якщо ж залишите Його, Він залишить вас.","Багато днів Ізраїль буде без Бога істинного, і без священика, який вчить, і без закону;","але коли він навернеться у скруті своїй до Господа Бога Ізраїлевого і знайде Його, Він дасть їм знайти Себе.","У ті часи не буде миру ні для того, хто виходить, ні для того, хто входить, бо великі заворушення будуть у всіх жителів земель;","народ буде воювати з народом, і місто з містом, тому що Бог приведе їх у сум’яття всякими бідами.","Але ви зміцнитеся, і нехай не слабшають руки ваші, тому що є відплата за діла ваші.","Коли почув Аса слова ці і пророцтво [Азарії], сина Одеда пророка, то підбадьорився і викинув мерзоти язичницькі з усієї землі Іудиної і Веніамінової і з міст, які він узяв на горі Єфремовій, і оновив жертовник Господній, що перед притвором Господнім.","І зібрав всього Іуду і Веніаміна і тих, що живуть з ними, переселенців від Єфрема і Манассії і Симеона; тому що багато хто від Ізраїля перейшли до нього, коли побачили, що Господь, Бог його, з ним.","І зібралися в Єрусалимі у третій місяць, у п’ятнадцятий рік царювання Аси;","і принесли в день той жертву Господу зі здобичі, яку привели, з великої худоби сімсот і з дрібної сім тисяч;","і вступили в завіт, щоб шукати Господа Бога батьків своїх від усього серця свого і від усієї душі своєї;","а всякий, хто не стане шукати Господа Бога Ізраїлевого, повинен померти, малий він чи великий, чоловік чи жінка.","І клялися Господу голосно і з вигуками і при звуках труб і рогів.","І раділи всі юдеї цій клятві, тому що від усього серця свого клялися і з усією щирістю шукали Його, і Він дав їм знайти Себе. І дав їм Господь спокій з усіх боків.","І Мааху, матір свою, цар Аса позбавив царського достоїнства за те, що вона зробила ідола для діброви. І зруйнував Аса ідола її, і порубав на шматки, і спалив у долині Кедрона.","Хоча висоти не були знищені в Ізраїлі, але серце Аси було цілком віддане Господу в усі дні його.","І вніс він посвячене батьком його і свою посвяту в дім Божий, срібло і золото і сосуди.","І не було війни до тридцять п’ятого року царювання Аси."],"x":{"2":"4.20.1|4.31.16-17|31.55.6","3":"38.3.4|40.8.11","4":"29.1.2","6":"50.24.6","7":"52.21.19|63.15.58|65.6.9","12":"5.24.24-25|4.6.5","13":"13.22.9","16":"10.15.13","17":"10.15.14|52.1.6","18":"13.5.1"}},{"v":["У тридцять шостий рік царювання Аси, пішов Вааса, цар Ізраїльський, на юдеїв і почав будувати Раму, щоб не дозволити нікому ні відходити від Аси, царя Юдейського, ні приходити до нього.","І виніс Аса срібло і золото зі скарбниць дому Господнього і дому царського і послав до Венадада, царя Сирійського, який жив у Дамаску, говорячи:","союз нехай буде між мною і тобою, як був між батьком моїм і батьком твоїм; ось, я посилаю тобі срібло і золото: піди, розірви союз твій з Ваасою, царем Ізраїльським, щоб він відступив від мене.","І послухався Венадад царя Аси і послав воєначальників, які були в нього, проти міст ізраїльських, і вони спустошили Ійон і Дан й Авелмаїм і всі запаси в містах Неффалимових.","І коли почув про це Вааса, то перестав будувати Раму і припинив роботу свою.","Аса ж цар зібрав усіх юдеїв, і вони вивезли з Рами камені і дерева, які використовував Вааса для будівлі, — і побудував з них Геву і Мицфу.","У той час прийшов Ананій прозорливець до Аси, царя Юдейського, і сказав йому: оскільки ти понадіявся на царя Сирійського і не уповав на Господа Бога твого, тому і врятувалося військо царя Сирійського від руки твоєї.","Чи не були ефіопляни і лівіяни з силою більшою і з колісницями і вершниками дуже численними? Але оскільки ти уповав на Господа, то Він віддав їх у руки твої,","тому що очі Господа оглядають усю землю, щоб підтримувати тих, чиє серце цілком віддане Йому. Нерозважливо ти зробив тепер. За те віднині будуть у тебе війни.","І розгнівався Аса на прозорливця, і замкнув його у в’язницю, тому що за це був у роздратуванні на нього; пригноблював Аса і декого з народу в той час.","І ось, діяння Аси, перші й останні, описані в книзі царів юдейських та ізраїльських.","І захворів Аса на ноги на тридцять дев’ятому році царювання свого, і хвороба його піднялася до верхніх частин тіла; але він у хворобі своїй шукав не Господа, а лікарів.","І спочив Аса з батьками своїми, і помер на сорок першому році царювання свого.","І поховали його у гробниці, яку він влаштував для себе в місті Давидовому; і поклали його на одрі, який наповнили пахощами і різними належно зробленими мастями, і спалили їх для нього безліч."],"x":{"1":"10.15.17","2":"10.15.18|11.12.18","4":"10.15.20","5":"10.15.21","6":"5.18.24","7":"13.19.2","8":"13.14.9|31.20.5","9":"22.9.5","13":"10.15.24"}},{"v":["І став царем Іосафат, син його, замість нього; і зміцнився він проти ізраїльтян.","І поставив він військо в усі укріплені міста Юдеї і розставив охоронне військо по землі Юдейській і по містах Єфремових, якими оволодів Аса, батько його.","І був Господь з Іосафатом, бо він ходив першими путями Давида, батька свого, і не шукав Ваалів,","але шукав він Бога батька свого і робив за заповідями Його, а не за діяннями ізраїльтян.","І утвердив Господь царство в руках його, і давали всі юдеї дари Іосафату, і було в нього багато багатства і слави.","І піднеслося серце його на путях Господніх; крім того, і висоти скасував він і діброви в Юдеї.","І в третій рік царювання свого він послав князів своїх Бенхаїла й Овадію, і Захарію і Нафанаїла і Михея, щоб учили по містах Іудиних народ,","і з ними левитів: Шемаію і Нефанію, і Зевадію й Азаїла, і Шемирамофа й Іонафана, й Адонію і Товію і Тов-Адонію, і з ними Елишаму й Іорама, священиків.","І вони навчали в Юдеї, маючи з собою книгу закону Господнього; і обходили всі міста Юдеї й учили народ.","І був страх Господній на всіх царствах землі, які навколо Юдеї, і не воювали з Іосафатом.","А від филистимлян приносили Іосафату дари і в данину срібло; також аравитяни приганяли до нього дрібну худобу: баранів сім тисяч сімсот і козлів сім тисяч сімсот.","І піднімався Іосафат усе більше і більше і побудував у Юдеї фортеці й міста для запасів.","Багато було в нього запасів у містах юдейських, а в Єрусалимі людей військових, хоробрих.","І ось список їх за поколіннями їхніми: в Іуди начальники тисяч: Адна начальник, і в нього відмінних воїнів триста тисяч;","за ним Іоханан начальник, і в нього двісті вісімдесят тисяч;","за ним Амасія, син Зихри, який присвятив себе Господу, і в нього двісті тисяч воїнів відмінних.","У Веніаміна: відмінний воїн Елиада, і в нього озброєних луком і щитом двісті тисяч;","за ним Ієгозавад, і в нього сто вісімдесят тисяч озброєних воїнів.","Ось ті, що служили царю, зверх тих, яких розставив цар в укріплених містах по всій Юдеї."],"x":{"1":"10.15.24","3":"13.19.3","5":"10.22.44|13.18.1","10":"13.14.14","16":"3.6.2"}},{"v":["І було в Іосафата багато багатства і слави; і поріднився він з Ахавом.","І пішов через кілька років до Ахава в Самарію; і заколов для нього Ахав багато худоби дрібної і великої, і для людей, які були з ним, і схиляв його йти на Рамоф галаадський.","І говорив Ахав, цар Ізраїльський, Іосафату, царю Юдейському: чи підеш зі мною в Рамоф галаадський? Той сказав йому: як ти, так і я, як твій народ, так і мій народ: йду з тобою на війну!","І сказав Іосафат царю Ізраїльському: запитай сьогодні, що скаже Господь.","І зібрав цар Ізраїльський пророків чотириста чоловік і сказав їм: чи йти нам на Рамоф галаадський війною, чи утриматися? Вони сказали: йди, і Бог віддасть його в руку царя.","І сказав Іосафат: чи немає тут ще пророка Господнього? запитаємо й у нього.","І сказав цар Ізраїльський Іосафату: є ще один чоловік, через якого можна запитати Господа; але я не люблю його, тому що він не пророкує про мене добре, а постійно пророкує лихе; це Михей, син Іємвлая. І сказав Іосафат: не говори так, царю.","І покликав цар Ізраїльський одного євнуха, і сказав: сходи скоріше за Михеєм, сином Іємвлая.","Цар же Ізраїльський та Іосафат, цар Юдейський, сиділи кожен на своєму престолі, одягнені в царський одяг; сиділи на площі біля воріт Самарії, і всі пророки пророкували перед ними.","І зробив собі Седекія, син Хенаани, залізні роги і сказав: так говорить Господь: цими поколеш сиріян до знищення їх.","І всі пророки пророкували те саме, говорячи: йди на Рамоф галаадський; буде успіх тобі, і віддасть його Господь у руку царя.","Посланий, який пішов покликати Михея, говорив йому: ось, пророки одноголосно пророкують добре цареві; нехай би і твоє слово було таким самим, як кожного з них: проречи і ти добре.","І сказав Михей: живий Господь, — що скаже мені Бог мій, те проречу я.","І прийшов він до царя, і сказав йому цар: Михею, чи йти нам війною на Рамоф галаадський, чи утриматися? І сказав той: ідіть, буде вам успіх, і вони будуть віддані в руки ваші.","І сказав йому цар: скільки разів мені заклинати тебе, щоб ти не говорив мені нічого, крім істини, в ім’я Господнє?","Тоді Михей сказав: я бачив усіх синів Ізраїля, розсіяних по горах, як овець, у яких немає пастиря, — і сказав Господь: немає в них начальника, нехай повернуться кожен у дім свій з миром.","І сказав цар Ізраїльський Іосафату: чи не говорив я тобі, що він не пророкує про мене доброго, а тільки лихе?","І сказав Михей: так вислухайте слово Господнє: я бачив Господа, Який сидить на престолі Своєму, і все воїнство небесне стояло праворуч і ліворуч Нього.","І сказав Господь: хто втягнув би Ахава, царя Ізраїльського, щоб він пішов і впав у Рамофі галаадському? І один говорив так, інший говорив інакше.","І виступив один дух, і став перед лицем Господа, і сказав: я втягну його. І сказав йому Господь: чим?","Той сказав: я вийду, і буду духом неправди у вустах усіх пророків його. І сказав Він: ти втягнеш його, і досягнеш; піди і зроби так:","І тепер, ось попустив Господь духу неправди увійти в уста цих пророків твоїх, але Господь прорік тобі недобре.","І підійшов Седекія, син Хенаани, і вдарив Михея по щоці, і сказав: якою це дорогою відійшов від мене Дух Господній, щоб говорити в тобі?","І сказав Михей: ось, ти побачиш це в той день, коли будеш бігати з кімнати в кімнату, щоб сховатися.","І сказав цар Ізраїльський: візьміть Михея і відведіть його до Амона градоначальника і до Іоаса, сина царя,","і скажіть: так говорить цар: посадіть цього у в’язницю і годуйте його хлібом і водою бідно, доки я не повернуся в мирі.","І сказав Михей: якщо ти повернешся в мирі, то не Господь говорив через мене. І сказав: слухайте це, всі люди!","І пішов цар Ізраїльський та Іосафат, цар Юдейський, до Рамофа галаадського.","І сказав цар Ізраїльський Іосафату: я переодягнуся і вступлю в битву, а ти вдягни свій царський одяг. І переодягся цар Ізраїльський, і вступив у битву.","І цар Сирійський повелів начальникам колісниць, які були в нього, сказавши: не бийтеся ні з малим, ні з великим, а тільки з одним царем Ізраїльським.","І коли побачили Іосафата начальники колісниць, то подумали: це цар Ізраїльський, — і оточили його, щоб битися з ним. Але Іосафат закричав, і Господь допоміг йому, і відвів їх Бог від нього.","І коли побачили начальники колісниць, що це не був цар Ізраїльський, то повернули від нього.","Тим часом один чоловік випадково натягнув лук свій, і поранив царя Ізраїльського крізь шви лат. І сказав він візнику: поверни назад, і вези мене від війська, тому що я поранений.","Але битва у той день посилилася; і цар Ізраїльський стояв на колісниці проти сиріян до вечора і помер, коли заходило сонце."],"x":{"1":"13.17.5|11.8.18","2":"10.22.2","3":"10.22.4","5":"10.22.6","6":"10.22.7","8":"10.22.9","10":"10.22.11","12":"10.22.13","16":"3.27.17|10.22.17","20":"10.22.21|24.1.6","21":"53.8.44|58.4.6|10.22.22","22":"31.19.14|36.14.9","23":"32.20.2|51.14.65|53.18.22","24":"10.20.30:39","29":"10.22.30","31":"10.22.32|25.65.9","33":"10.22.34","34":"10.22.35"}},{"v":["І повертався Іосафат, цар Юдейський, у мирі в дім свій в Єрусалим.","І виступив назустріч йому Іиуй, син Ананії, прозорливець, і сказав царю Іосафату: чи слід було тобі допомагати нечестивцю і любити ненависників Господа? за це на тебе гнів від лиця Господа.","Втім, і добре знайдено в тобі, тому що ти знищив ідолів у землі [Юдейській] і налаштував серце своє для того, щоб шукати Бога.","І жив Іосафат в Єрусалимі. І знову став він обходити народ свій від Вирсавії до гори Єфремової, і навертав їх до Господа, Бога батьків їхніх.","І поставив суддів на землі по всіх укріплених містах Юдеї в кожнім місті,","і сказав суддям: дивіться, що ви робите, ви чините не суд людський, але суд Господа; і Він з вами у справі суду.","Отже, нехай буде страх Господній на вас: дійте обачно, тому що немає у Господа Бога нашого неправди, ні упереджености, ні хабарництва.","І в Єрусалимі приставив Іосафат деяких з левитів і священиків і глав поколінь в Ізраїлі — до суду Господнього і до позовів. І повернулися в Єрусалим.","І дав їм повеління, говорячи: так дійте у страху Господньому, з вірністю і з чистим серцем:","у всякій справі спірній, яка надійде до вас від братів ваших, що живуть у містах своїх, чи про кровопролиття, чи про закон, заповіді, устави й обряди, наставляйте їх, щоб вони не завинили перед Господом, і не було б гніву Його на вас і на братів ваших; так дійте, — і ви не згрішите.","І ось Амарія первосвященик над вами у всякій справі Господній, а Зевадія, син Ісмаїлів, князь дому Іудиного, в усякій справі царя, і наглядачі левити перед вами. Будьте тверді і дійте, і буде Господь з добрим."],"x":{"2":"10.16.1","3":"10.14.13|13.12.12|17.9.8","5":"4.16.18","6":"4.1.17|25.81.2|29.6.4","7":"4.10.17|24.34.19|29.6.7|30.35.12|54.10.34|56.1.17|62.2.11|65.2.6|66.6.9|68.3.25","10":"4.17.8","11":"48.3.7"}},{"v":["Після цього моавитяни й аммонитяни, а з ними деякі з країни Маонитської, пішли війною на Іосафата.","І прийшли, і донесли Іосафату, говорячи: йде на тебе безліч велика з-за моря, від Сирії, і ось вони в Хацацон-Фамарі, тобто в Енгедді.","І злякався Іосафат, і навернув лице своє шукати Господа, й оголосив піст по всій Юдеї.","І зібралися юдеї просити допомоги у Господа; з усіх міст Іудиних прийшли вони благати Господа.","І став Іосафат на зібранні юдеїв та єрусалимлян у домі Господньому, перед новим двором,","і сказав: Господи Боже батьків наших! Чи не Ти Бог на небі? І Ти володарюєш над усіма царствами народів, і у Твоїй руці сила і міцність, і ніхто не встоїть проти Тебе!","Чи не Ти, Боже наш, вигнав жителів землі цієї перед лицем народу Твого Ізраїля і віддав її сімені Авраама, друга Твого, повік?","І вони оселилися на ній і побудували Тобі на ній святилище в ім’я Твоє, говорячи:","якщо прийде на нас біда: меч, що карає, або моровиця, або голод, то ми станемо перед домом цим і перед лицем Твоїм, бо ім’я Твоє в домі цьому, і закличемо Тебе в тісноті нашій, і Ти почуєш і спасеш.","І нині ось аммонитяни і моавитяни і жителі гори Сеїра, через землі яких Ти не дозволив пройти ізраїльтянам, коли вони йшли із землі Єгипетської, а тому вони оминули їх і не знищили їх, —","ось вони платять нам тим, що прийшли вигнати нас зі спадкоємного володіння Твого, яке Ти віддав нам.","Боже наш! Ти суди їх. Бо немає в нас сили проти безлічі цієї великої, що прийшла на нас, і ми не знаємо, що́ робити, але до Тебе очі наші!","І всі юдеї стояли перед лицем Господнім, і малі діти їхні, дружини їхні і сини їхні.","Тоді на Іозиїла, сина Захарієвого, сина Ванеї, сина Ієіела, сина Матфанії, левита із синів Асафових, зійшов Дух Господній серед зібрання","і сказав він: слухайте, всі юдеї і жителі Єрусалима і царю Іосафате! Так говорить Господь до вас: не бійтеся і не жахайтеся безлічі цієї великої, бо не ваша війна, а Божа.","Завтра виступите проти них: ось вони піднімаються на височину Циц, і ви знайдете їх в кінці долини, перед пустелею Ієруїлом.","Не вам воювати цього разу; ви станьте, стійте і дивіться на спасіння Господнє, що посилається вам. Іуда та Єрусалим! не бійтеся і не жахайтеся. Завтра виступите назустріч їм, і Господь буде з вами.","І схилився Іосафат лицем до землі, і всі юдеї і жителі Єрусалима впали перед Господом, щоб поклонитися Господу.","І встали левити із синів Каафових і з синів Кореєвих — хвалити Господа Бога Ізраїлева, голосом дуже гучним.","І встали вони рано-вранці, і виступили до пустелі Фекойської; і коли вони виступили, став Іосафат і сказав: послухайте мене, юдеї і жителі Єрусалима! Вірте Господу Богу вашому, і будьте твердими; вірте пророкам Його, і буде успіх вам.","І радився він з народом, і поставив співців Господу, щоб вони у благоліпності святині, виступаючи попереду озброєних, славословили і говорили: славте Господа, бо повіки милість Його!","І в той час, як вони стали викликувати і славословити, Господь збудив незгоду між аммонитянами, моавитянами і жителями гори Сеїра, які прийшли на Юдею, і були вони вражені:","бо повстали аммонитяни і моавитяни на жителів гори Сеїра, вбиваючи і знищуючи їх, а коли покінчили з жителями Сеїра, тоді стали знищувати одне одного.","І коли юдеї прийшли на височину до пустелі і глянули на ту багатолюдність, і ось — трупи лежать на землі, і нема уцілілого.","І прийшов Іосафат і народ його забирати здобич, і знайшли в них безліч і майна, і одягу, і коштовних речей, і набрали собі стільки, що не могли нести. І три дні вони забирали здобич; така велика була вона!","А на четвертий день зібралися в долині благословення, бо там вони благословили Господа. Тому і називають те місце долиною благословення до цього дня.","І пішли назад усі юдеї та єрусалимляни й Іосафат на чолі їх, щоб повернутися в Єрусалим з радістю, тому що дав їм Господь торжество над ворогами їхніми.","І прийшли в Єрусалим з псалтирями, і цитрами, і трубами, до дому Господнього.","І був страх Божий на всіх царствах земних, коли вони почули, що Сам Господь воював проти ворогів Ізраїля.","І спокійним стало царство Іосафатове, і дав йому Бог його спокій з усіх боків.","Так царював Іосафат над Юдеєю: тридцяти п’яти років він був, коли став царем, і двадцять п’ять років царював у Єрусалимі. Ім’я матері його Азува, дочка Салаїла.","І ходив він путями батька свого Аси і не ухилився від них, роблячи угодне в очах Господніх.","Тільки висоти не були скасовані, і народ ще не навернув твердо серця свого до Бога батьків своїх.","Інші діяння Іосафата, перші й останні, описані в записах Іиуя, сина Ананієвого, які внесені в книгу царів Ізраїлевих.","Але після того вступив Іосафат, цар Юдейський, у спілкування з Охозією, царем Ізраїльським, який чинив беззаконня,","і з’єднався з ним, щоб побудувати кораблі для відправлення у Фарсис; і побудували вони кораблі в Еціон-Гавері.","І вирік тоді Єлиєзер, син Додави з Мареші, пророцтво на Іосафата, говорячи: оскільки ти вступив у спілкування з Охозією, то зруйнував Господь справу твою. — І розбилися кораблі, і не могли йти у Фарсис."],"x":{"2":"0.14.7|5.15.62","3":"13.17.3","6":"25.8.2|25.46.8-9|13.14.11","7":"31.41.8|53.8.33|55.2.23","9":"13.6.28","10":"4.2.9","12":"25.24.15|25.120.1|50.8.25","14":"6.11.29|13.24.20","15":"1.14.13|5.10.14|31.33.2","17":"1.14.13|3.14.9","20":"9.14.2|25.45.1-2|1.14.31","23":"6.7.22|8.14.20","29":"13.14.14","30":"13.14.6","31":"10.22.42","33":"10.22.43","34":"10.22.45","35":"10.22.4","36":"10.22.48"}},{"v":["І спочив Іосафат з батьками своїми, і похований з батьками своїми в місті Давидовому. І став царем Іорам, син його, замість нього.","І в нього були брати, сини Іосафата: Азарія та Ієхиїл, і Захарія й Азарія, і Михаїл і Сафатія: усі ці сини Іосафата, царя Ізраїлевого.","І дав їм батько їхній великі подарунки сріблом і золотом і коштовностями, разом з укріпленими містами в Юдеї; царство ж віддав Іораму, тому що він первісток.","І вступив Іорам на царство батька свого й утвердився, й умертвив усіх братів своїх мечем і також деяких із князів Ізраїлевих.","Тридцяти двох років був Іорам, коли став царем, і вісім років царював у Єрусалимі;","і ходив він шляхом царів ізраїльських, як робив дім Ахавів, тому що дочка Ахава була дружиною його, — і робив він неугодне в очах Господніх.","Однак же не хотів Господь погубити дім Давида заради завіту, який уклав з Давидом, і тому що обіцяв дати йому світильник і синам його на всі часи.","У дні його вийшов Едом з-під влади Іуди, і поставили над собою царя.","І пішов Іорам з воєначальниками своїми, і всі колісниці з ним; і вставши вночі, вразив ідумеян, які оточили його і начальників над колісницями [і побіг народ в оселі свої].","Однак вийшов Едом з-під влади Іуди до цього дня. У той же час вийшла і Ливна з-під влади його, тому що він залишив Господа Бога батьків своїх.","Також висоти спорудив він на горах юдейських, і ввів у блуд жителів Єрусалима і спокусив Юдею.","І прийшов до нього лист від Іллі пророка, в якому було сказано: так говорить Господь Бог Давида, батька твого: за те, що ти не пішов путями Іосафата, батька твого, і путями Аси, царя Юдейського,","а пішов шляхом царів ізраїльських і ввів у блуд Юдею і жителів Єрусалима, як вводив у блуд дім Ахавів, ще ж і братів твоїх, дім батька твого, які кращі за тебе, ти умертвив,","за те, ось Господь уразить поразкою великою народ твій і синів твоїх, і дружин твоїх, і все майно твоє,","тебе ж самого – хворобою тяжкою, хворобою нутрощів твоїх до того, що будуть випадати нутрощі твої від хвороби день у день.","І збудив Господь проти Іорама дух филистимлян і аравитян, суміжних з ефіоплянами;","і вони пішли на Юдею й увірвалися в неї, і захопили все майно, що знаходилося в домі царя, також і синів його і дружин його; і не залишилося в нього сина, крім Охозії, меншого із синів його.","А після всього цього вразив Господь нутрощі його хворобою невиліковною.","Так було день за днем, а до кінця другого року випали нутрощі його від хвороби його, і він помер у жорстоких стражданнях; і не спалив для нього народ його пахощів, як робив те для батьків його.","Тридцяти двох років був він, коли став царем, і вісім років царював у Єрусалимі, і відійшов неоплаканий, і поховали його в місті Давидовому, але не в царських гробницях."],"x":{"1":"10.22.50","4":"11.8.16","5":"11.8.17","6":"11.8.18|13.18.1","7":"9.7.12","8":"0.27.40|11.8.20","11":"2.17.7|2.20.5|10.13.2","12":"10.15.26","20":"11.8.17:24"}},{"v":["І поставили царем жителі Єрусалима Охозію, меншого сина його, замість нього, тому що всіх старших побило полчище, яке приходило з аравитянами до стану, — і став царем Охозія, син Іорама, царя Юдейського.","Двадцяти двох років був Охозія, коли став царем, і один рік царював у Єрусалимі; ім’я матері його Гофолія, дочка Амврія.","Він також ходив путями дому Ахавового, тому що мати його була радницею йому на беззаконні справи.","І робив він неугодне в очах Господніх, подібно до дому Ахавого, тому що він був йому радником, після смерти батька його, на загибель йому.","Також за їх порадою, він пішов з Іорамом, сином Ахавовим, царем Ізраїльським, на війну проти Азаїла, царя Сирійського, у Рамоф галаадський. І поранили сиріяни Іорама,","і повернувся він у Ізреель лікуватися від ран, які завдали йому в Рамі, коли він воював з Азаїлом, царем Сирійським. І Охозія, син Іорама, цар Юдейський, прийшов відвідати Іорама, сина Ахавового, в Ізреель, бо той був хворий.","І від Бога було це на загибель Охозії, що він прийшов до Іорама: тому що, після приходу свого, він вийшов з Іорамом проти Іиуя, сина Намессієвого, якого помазав Господь на знищення дому Ахавового.","Коли вершив Іиуй суд над домом Ахава, тоді він знайшов князів юдейських і синів братів Охозії, які служили Охозії, й умертвив їх.","І [звелів] він шукати Охозію, і взяли його, коли він ховався в Самарії, і привели його до Іиуя, і умертвили його, і поховали його, бо говорили: він син Іосафата, який шукав Господа від усього серця свого. І не залишилося в домі Охозії того, хто міг би царювати.","Бо Гофолія, мати Охозії, побачивши, що помер син її, встала і знищила все царське плем’я дому Іуди.","Але Іосавеф, дочка царя, взяла Іоаса, сина Охозії, і викрала його із середовища царських синів, яких умертвляли, і помістила його і годувальницю його в спальній кімнаті; і в такий спосіб Іосавеф, дочка царя Іорама, дружина Іодая священика, сестра Охозії, сховала Іоаса від Гофолії, і вона не умертвила його.","І був він у них у домі Божому переховуваний шість років; Гофолія ж царювала над землею."],"x":{"1":"11.8.24","2":"11.8.26","3":"11.8.27","5":"11.8.28|5.20.8","6":"11.8.29","7":"10.12.15|11.9.6","8":"10.19.17|11.9.24","9":"11.9.27-28","10":"11.11.1","11":"11.11.2"}},{"v":["Але в сьомий рік підбадьорився Іодай і прийняв у союз з собою начальників сотень: Азарію, сина Ієрохамового, й Ісмаїла, сина Ієгохананового, й Азарію, сина Оведового, і Маасею, сина Адаії, і Елишафата, сина Зихрі.","І вони пройшли по Юдеї і зібрали левитів з усіх міст Юдеї і глав поколінь Ізраїлевих, і прийшли в Єрусалим.","І уклало все зібрання союз у домі Божому з царем. І сказав їм Іодай: ось син царя повинен бути царем, як вирік Господь про синів Давидових.","Ось що ви зробіть: третина вас, що приходять у суботу, зі священиків і левитів, буде воротарями біля порогів,","і третина при домі царському, і третина біля воріт Ієсод, а весь народ на дворах дому Господнього.","І ніхто нехай не входить у дім Господній, крім священиків і службовців з левитів. Вони можуть увійти, тому що освячені; весь же народ нехай стоїть на сторожі Господній.","І нехай левити оточать царя з усіх боків, кожен зі зброєю своєю в руці своїй, і хто буде входити в храм, нехай буде умертвлений. І будьте ви при царі, коли він буде входити і виходити.","І зробили левити й усі юдеї, як наказав Іодай священик; і взяли кожен людей своїх, які приходять у суботу, з тими, що відходять у суботу, тому що не відпустив священик Іодай чергу, яка змінялася.","І роздав Іодай священик начальникам сотень списи і малі й великі щити царя Давида, що були в домі Божому;","і поставив весь народ, кожного зі зброєю його в руці його, від правої сторони храму до лівої сторони храму, біля жертовника й біля дому, навколо царя.","І вивели сина царя, і поклали на нього вінець і прикраси, і поставили його царем; і помазали його Іодай і сини його і сказали: нехай живе цар!","І почула Гофолія голос народу, який біжить і проголошує про царя, і вийшла до народу в дім Господній,","і побачила: і ось цар стоїть на підвищенні своєму при вході, і князі і труби біля царя, і весь народ землі веселиться, і сурмлять трубами, і співці з інструментами музичними і вправні у славослів’ї. І роздерла Гофолія одяг свій і закричала: змова! змова!","І викликав Іодай священик начальників сотень, які начальствують над військом, і сказав їм: виведіть її геть [із храму], і хто піде за нею, той буде умертвлений мечем. Тому що священик сказав: не умертвляйте її в домі Господньому.","І дали їй місце, і коли вона прийшла до входу кінських воріт царського дому, там умертвили її.","І уклав Іодай завіт між собою і між усім народом і царем, щоб бути їм народом Господнім.","І пішов весь народ у капище Ваала, і зруйнували його, і жертовники його й ідолів його розтрощили; і Матфана, жерця Ваалового, умертвили перед жертовниками.","І доручив Іодай справи дому Господнього священикам і левитам, [і відновив денні черги священиків і левитів,] як розподілив Давид у домі Господньому, для возношення всепалень Господу, як написано в законі Мойсеєвому, з радістю і співом, за уставом Давидовим.","І поставив він воротарів біля воріт дому Господнього, щоб не міг входити нечистий чого-небудь.","І взяв начальників сотень, і вельмож, і начальників у народі, і весь народ землі, і провів царя з дому Господнього, і пройшли через верхні ворота в дім царський, і посадили царя на царський престіл.","І веселився весь народ землі, і місто заспокоїлося. А Гофолію умертвили мечем."],"x":{"1":"11.11.4","3":"9.7.13","4":"11.11.5","5":"11.11.6","6":"3.8.6|3.16.5|14.8.28-29","9":"11.11.10","11":"11.11.12|4.17.18","12":"11.11.13","13":"11.11.14|3.10.10","14":"11.11.15","15":"11.11.16","16":"11.11.17","17":"11.11.18","18":"13.29.25|2.1.3","20":"11.11.19","21":"11.11.20"}},{"v":["Семи років був Іоас, коли став царем, і сорок років царював у Єрусалимі; ім’я матері його Цив’я з Вирсавії.","І робив Іоас угодне в очах Господніх в усі дні Іодая священика.","І взяв йому Іодай двох дружин, і він мав від них синів і дочок.","І після цього прийшло на серце Іоасу оновити дім Господній,","і зібрав він священиків і левитів і сказав їм: підіть по містах Юдеї і збирайте з усіх ізраїльтян срібло для підтримки дому Бога вашого щорічно, і поспішіть у цій справі. Але не поспішили левити.","І прикликав цар Іодая, главу їх, і сказав йому: чому ти не вимагаєш від левитів, щоб вони доставляли з Юдеї та Єрусалима данину, встановлену Мойсеєм, рабом Господнім, і зібранням ізраїльтян для скинії зібрання?","Бо нечестива Гофолія і сини її розорили дім Божий і все присвячене для дому Господнього вжили для Ваалів.","І наказав цар, і зробили один ящик, і поставили його біля входу в дім Господній іззовні.","І проголосили по Юдеї та Єрусалиму, щоб приносили Господу данину, *накладену Мойсеєм, рабом Божим, на ізраїльтян у пустелі.","І зраділи всі начальники і весь народ, і приносили і клали в ящик, доки він не наповнився.","У той час, коли левити приносили ящик до царських чиновників, і коли вони бачили, що срібла багато, приходили писар царя і довірений первосвященика, і висипали з ящика, і відносили його і ставили його на своє місце. Так робили вони з дня у день, і зібрали безліч срібла.","І віддавали його цар та Іодай виконавцям робіт у домі Господньому, і вони наймали каменотесів і теслярів для оновлення дому Господнього, також ковалів і мідників для зміцнення дому Господнього.","І працювали виконавці робіт, і звершилося відновлення руками їхніми, і привели дім Божий у належний стан його, й укріпили його.","І закінчивши все, вони представили царю та Іодаю залишок срібла. І зробили з нього сосуди для дому Господнього, сосуди службові і для всепалень, чаші й інші сосуди золоті і срібні. І приносили всепалення в домі Господньому постійно в усі дні Іодая.","І постарів Іодай і, наситившись днями життя, помер: сто тридцять років було йому, коли він помер.","І поховали його в місті Давидовому з царями, тому що він робив добре в Ізраїлі і для Бога, і для дому Його.","Але після смерти Іодая прийшли князі юдейські і поклонилися цареві; тоді цар став слухати їх.","І залишили дім Господа Бога батьків своїх і стали служити деревам священним та ідолам, — і був гнів Господній на Іуду та Єрусалим за цю провину їх.","І Він посилав до них пророків для навернення їх до Господа, і вони застерігали їх, але ті не слухали.","І Дух Божий зійшов на Захарію, сина Іодая священика, і він став на підвищенні перед народом і сказав їм: так говорить Господь: для чого ви переступаєте повеління Господні? не буде успіху вам; і як ви залишили Господа, так і Він залишить вас.","І змовилися проти нього, і побили його камінням, за наказом царя [Іоаса], у дворі дому Господнього.","І не згадав цар Іоас про благодіяння, яке зробив йому Іодай, батько його, й убив сина його. І він умираючи говорив: нехай бачить Господь і нехай воздасть!","І після закінчення року виступило проти нього військо сирійське, і ввійшли в Юдею і в Єрусалим, і знищили всіх князів народу, і всю здобич, взяту в них, відіслали до царя в Дамаск.","Хоча невеликою кількістю людей приходило військо сирійське, але Господь віддав до руки їх дуже численну силу за те, що залишили Господа Бога батьків своїх. І над Іоасом учинили вони суд,","і коли вони пішли від нього, залишивши його в тяжкій хворобі, то зробили проти нього змову раби його, за кров сина Іодая священика, й убили його на постілі його, і він помер. І поховали його в місті Давидовому, але не поховали його в царських гробницях.","Змовниками ж проти нього були: Завад, син Шимеафи аммонитянки, та Ієгозавад, син Шимрифи моавитянки.","Про синів його і про численні пророцтва проти нього і про влаштування дому Божого написано в книзі царів. І став царем Амасія, син його, замість нього."],"x":{"1":"11.12.1","2":"11.12.2","5":"11.12.5","6":"1.35.5","7":"11.11.1","8":"11.12.9","9":"1.35.5","11":"11.12.10","12":"11.12.11","13":"11.12.14","14":"11.12.11","17":"11.12.2","19":"13.33.10","20":"13.15.2","21":"50.23.35|52.11.50-51","23":"11.12.18","24":"13.12.1","25":"11.12.20","26":"11.12.21","27":"11.12.1:21"}},{"v":["Двадцяти п’яти років став царем Амасія і двадцять дев’ять років царював у Єрусалимі; ім’я матері його Ієгоаддань з Єрусалима.","І робив він угодне в очах Господніх, але не від повного серця.","Коли утвердилося за ним царство, тоді він умертвив рабів своїх, які убили царя, батька його.","Але дітей їхніх не умертвив, тому що написано в законі, у книзі Мойсеєвій, де заповів Господь, говорячи: не повинні бути умертвлені батьки за дітей, і дітей не слід умертвляти за батьків, але кожен за свій злочин повинен померти.","І зібрав Амасія юдеїв і поставив їх за поколіннями під владу тисячоначальників і стоначальників, усіх юдеїв і веніамитян, і перерахував їх від двадцяти років і вище, і знайшов їх триста тисяч людей добірних, які ходять на війну, які тримають спис і щит.","І ще найняв з ізраїльтян сто тисяч хоробрих воїнів за сто талантів срібла.","Але чоловік Божий прийшов до нього і сказав: царю! нехай не йде з тобою військо ізраїльське, тому що немає Господа з ізраїльтянами, з усіма синами Єфрема.","Але йди ти один, роби справу, мужньо подвизайся на війні. Інакше повалить тебе Бог перед лицем ворога, бо є сила у Бога підтримати і повалити.","І сказав Амасія чоловіку Божому: що ж робити зі ста талантами, які я віддав війську ізраїльському? І сказав чоловік Божий: може Господь дати тобі більше за це.","І відокремив їх Амасія, — військо, яке прийшло до нього з землі Єфремової, — щоб вони йшли у своє місце. І сильно запалав гнів їх на Юдею, і вони пішли назад у своє місце, палаючи у гніві.","А Амасія наважився і повів народ свій, і пішов у долину Соляну і побив синів Сеїра десять тисяч;","і десять тисяч живих узяли сини Іудині в полон, і привели їх на вершину скелі, і скинули їх з вершини скелі, й усі вони розбилися зовсім.","Військо ж, яке Амасія відіслав назад, щоб воно не ходило з ним на війну, розсипалося по містах Юдеї від Самарії до Вефорона і перебило в них три тисячі, і награбувало багато здобичі.","Амасія, прийшовши після поразки ідумеян, приніс богів синів Сеїра і поставив їх у себе богами, і перед ними кланявся і їм кадив.","І запалав гнів Господа на Амасію, і послав Він до нього пророка, і той сказав йому: навіщо ти вдаєшся до богів народу цього, які не визволили народу свого від руки твоєї?","Коли він говорив йому, цар відповів: хіба поставили тебе радником царським? перестань, щоб не убили тебе. І перестав пророк, сказавши: знаю, що вирішив Бог погубити тебе, тому що ти зробив це і не слухаєш поради моєї.","І порадився Амасія, цар Юдейський, і послав до Іоаса, сина Іоахаза, сина Іиуя, царя Ізраїльського, сказати: виходь, побачимось особисто.","І послав Іоас, цар Ізраїльський, до Амасії, царя Юдейського, сказати: терен, що на Ливані, послав до кедра, що на Ливані ж, сказати: віддай дочку свою за дружину синові моєму. Але прийшли звірі дикі, які на Ливані, і потоптали цей терен.","Ти говориш: ось я побив ідумеян, — і піднеслося серце твоє до марнославства. Сиди краще у себе вдома. До чого тобі затівати небезпечну справу? Впадеш ти й Юдея з тобою.","Але не послухався Амасія, тому що від Бога було це, щоб віддати їх у руку Іоаса за те, що стали звертатися до богів ідумейських.","І виступив Іоас, цар Ізраїльський, і побачились особисто, він і Амасія, цар Юдейський, у Вефсамисі юдейському.","І були розбиті юдеї ізраїльтянами, і побігли кожен у намет свій.","І Амасію, царя Юдейського, сина Іоаса, сина Іоахазового, захопив Іоас, цар Ізраїльський, у Вефсамисі і привів його в Єрусалим, і зруйнував стіну Єрусалимську від воріт Єфремових до воріт наріжних, на чотириста ліктів;","і взяв усе золото і срібло, і всі сосуди, що знаходилися в домі Божому біля Овед-Едома, і скарби дому царського, і заручників, і повернувся в Самарію.","І жив Амасія, син Іоасів, цар Юдейський, після смерти Іоаса, сина Іоахазового, царя Ізраїльського, п’ятнадцять років.","Інші діла Амасії, перші й останні, описані в книзі царів юдейських та ізраїльських.","І після того часу, як Амасія відступив від Господа, вчинили проти нього змову в Єрусалимі, і він утік у Лахис. І послали за ним у Лахис, і умертвили його там.","І привезли його на конях, і поховали його з батьками його в місті Іудиному."],"x":{"1":"11.14.2","2":"11.14.3|13.26.4","3":"11.14.5|13.24.25","4":"4.24.16|11.14.6|36.18.20","5":"3.1.3","8":"13.20.15|25.32.17|25.61.7","11":"11.14.7","15":"4.32.37|6.10.14","17":"11.13.12","18":"16.4.13","20":"11.14.11|13.22.7","22":"11.14.12","23":"11.14.13","24":"11.14.14|12.26.15","25":"11.14.17","26":"11.14.1","27":"10.15.27|11.14.19"}},{"v":["І взяв весь народ юдейський Озію, якому було шістнадцять років, і поставили його царем на місце батька його Амасії.","Він оббудував Елаф і повернув його Юдеї, після того як спочив цар з батьками своїми.","Шістнадцяти років був Озія, коли став царем, і п’ятдесят два роки царював у Єрусалимі; ім’я матері його Ієхолія з Єрусалима.","І робив він угодне в очах Господніх точно так, як робив Амасія, батько його;","і звертався він до Бога у дні Захарії, який навчав страху Божого; і в ті дні, коли він звертався до Господа, сприяв йому Бог.","І він вийшов і воював з филистимлянами, і зруйнував стіни Гефа і стіни Іавнеї і стіни Азота; і побудував міста в області Азотській і у филистимлян.","І допомагав йому Бог проти филистимлян і проти аравитян, що живуть у Гур-Ваалі, і проти меунитян;","і давали аммонитяни данину Озії, і дійшло ім’я його до меж Єгипту, тому що він був дуже сильний.","І побудував Озія вежі в Єрусалимі над воротами наріжними і над воротами долини і на розі, і зміцнив їх.","І побудував вежі в пустелі, і зробив багато водойм, тому що мав багато худоби, і на низині і на рівнині, і хліборобів і садівників у горах і на Кармилі, бо він любив землеробство.","Було в Озії і військо, яке виходило на війну загонами, за рахунком у списку їх, складеним рукою Ієіела писаря і Маасеї наглядача, під проводом Хананії, одного з головних сановників царських.","Уся кількість глав поколінь, з хоробрих воїнів, була дві тисячі шістсот,","і під їхньою рукою військової сили — триста сім тисяч п’ятсот, які вступали у битву з військовою мужністю, на допомогу царю проти ворога.","І заготував для них Озія, для усього війська, щити і списи, і шоломи і лати, і луки і каміння для пращі.","І зробив він в Єрусалимі майстерно придумані машини, щоб вони знаходилися на вежах і на кутах для пускання стріл і великого каміння. І пронеслося ім’я його далеко, тому що він дивно огородив себе і зробився сильним.","Але коли він зробився сильним, загордилося серце його на загибель його, і він зробився злочинцем перед Господом Богом своїм, тому що ввійшов у храм Господній, щоб запалити фіміам на вівтарі кадильному.","І пішов за ним Азарія священик, і з ним вісімдесят священиків Господніх, людей відмінних,","і стали проти Озії царя і сказали йому: не тобі, Озіє, кадити Господеві; це справа священиків, синів Ааронових, посвячених для кадіння; вийди зі святилища, бо ти вчинив беззаконно, і не [буде] тобі це за честь у Господа Бога.","І розгнівався Озія, — а в руці в нього була кадильниця для кадіння; і коли він розгнівався на священиків, проказа з’явилася на чолі його, перед лицем священиків, у домі Господньому, біля вівтаря кадильного.","І глянув на нього Азарія первосвященик і всі священики; і ось у нього проказа на чолі його. І примушували його вийти звідти, та й сам він поспішав відійти, тому що вразив його Господь.","І був цар Озія прокаженим до дня смерти своєї, і жив в окремому домі і відлучений був від дому Господнього. А Іоафам, син його, був начальником над домом царським і управляв народом землі.","Інші діяння Озії, перші й останні, описав Ісая, син Амоса, пророк.","І спочив Озія з батьками своїми, і поховали його з батьками його на полі царських гробниць, тому що говорили: він прокажений. І став царем Іоафам, син його, замість нього."],"x":{"1":"11.14.21","3":"11.15.2","4":"11.15.3|13.25.2","5":"11.12.2","6":"40.1.8","16":"11.15.6|13.25.19|1.30.7","17":"12.6.10","18":"3.18.7|75.5.4","19":"11.5.27","21":"11.15.5","23":"11.15.7"}},{"v":["Двадцяти п’яти років був Іоафам, коли став царем, і шістнадцять років царював у Єрусалимі; ім’я матері його Ієруша, дочка Садока.","І робив він угодне в очах Господніх точно так, як робив Озія, батько його, тільки він не входив у храм Господній, і народ продовжував ще грішити.","Він побудував верхні ворота дому Господнього, і багато чого побудував на стіні Офела;","і міста побудував на горі Юдейській, і в лісах побудував палаци і вежі.","Він воював з царем аммонитян і подолав їх, і дали йому аммонитяни в той рік сто талантів срібла і десять тисяч ко́рів пшениці і ячменю десять тисяч. Це давали йому аммонитяни і на другий рік, і на третій.","Таким сильним був Іоафам тому, що йшов путями своїми перед лицем Господа Бога свого.","Інші діяння Іоафама і всі війни його і поведінка його описані в книзі царів ізраїльських та юдейських:","двадцяти п’яти років був він, коли став царем, і шістнадцять років царював у Єрусалимі.","І спочив Іоафам з батьками своїми, і поховали його в місті Давидовому. І став царем Ахаз, син його, замість нього."],"x":{"1":"11.15.33","2":"11.15.34","3":"17.3.26-27|17.11.21","7":"11.15.32","9":"11.15.38"}},{"v":["Двадцяти років був Ахаз, коли став царем, і шістнадцять років царював у Єрусалимі; і він не робив угодного в очах Господніх, як робив Давид, батько його:","він ішов путями царів ізраїльських, і навіть зробив відлиті статуї Ваалів;","і він звершував куріння в долині синів Еннома, і проводив синів своїх через вогонь, наслідуючи мерзоти народів, яких вигнав Господь перед лицем синів Ізраїлевих;","і приносив жертви і куріння на висотах і на пагорбах і під усяким гіллястим деревом.","І віддав його Господь Бог його в руки царя сиріян, і вони вразили його і взяли в нього багато полонених і відвели в Дамаск. Також і в руки царя Ізраїльського був він відданий, і той учинив над ним велику поразку.","І побив Факей, син Ремалиїн, [цар Ізраїльський,] юдеїв сто двадцять тисяч в один день, людей войовничих, тому що вони залишили Господа Бога батьків своїх.","Зихрій же, силач з єфремлян, убив Маасею, сина царя, й Азрикама, який був начальником над палацом, і Елкану, другого після царя.","І взяли сини Ізраїлеві в полон у братів своїх, юдеїв, двісті тисяч дружин, синів і дочок; також і багато здобичі награбували в них, і відправили здобич у Самарію.","Там був пророк Господній, ім’я його Одед. Він вийшов перед лице війська, яке йшло в Самарію, і сказав їм: ось Господь Бог батьків ваших, у гніві на юдеїв, віддав їх у руки ваші, і ви побили їх з такою люттю, яка досягла небес.","І тепер ви думаєте поневолити синів Іуди і Єрусалима на рабів і рабинь собі. А хіба на вас самих немає провини перед Господом Богом вашим?","Отже, послухайте мене, і поверніть полонених, яких ви захопили з братів ваших, бо полум’я гніву Господнього на вас.","І встали деякі з начальників синів Єфремових: Азарія, син Ієгоханана, Берехія, син Мешиллемофа, та Єзекія, син Шаллума, й Амаса, син Хадлая, проти тих, хто йшов з війни,","і сказали їм: не вводьте сюди полонених, тому що гріх був би нам перед Господом. Невже ви думаєте додати до гріхів наших і до злочинів наших? велика провина наша, і полум’я гніву [Господнього] над Ізраїлем.","І залишили озброєні полонених і здобич у воєначальників і всього зібрання.","І встали мужі, згадані за іменами, і взяли полонених, і всіх нагих з них одягли зі здобичі, — і одягли їх, і взули їх, і нагодували їх, і напоїли їх, і помазали їх єлеєм, і посадили на ослів усіх слабких з них, і відправили їх у Єрихон, місто пальм, до братів їхніх, і повернулися у Самарію.","У той час послав цар Ахаз до царів ассирійських, щоб вони допомогли йому,","тому що ідумеяни і ще приходили, і багатьох убили в Юдеї, і взяли в полон;","і филистимляни розсипалися по містах низинного краю і півдня Юдеї і взяли Вефсамис і Аїалон, і Гедероф і Сохо і залежні від нього міста, і Фимну і залежні від неї міста, і Гимзо і залежні від нього міста, й оселилися там.","Так принизив Господь юдеїв за Ахаза, царя Юдейського, тому що він розбестив Юдею і тяжко грішив перед Господом.","І прийшов до нього Феглафелласар, цар Ассирійський, але був за тягар йому, замість того, щоб допомогти йому,","тому що Ахаз узяв скарби з дому Господнього і дому царського й у князів і віддав цареві Ассирійському, але не на допомогу собі.","І в скрутний для себе час він продовжував беззаконно чинити перед Господом, він — цар Ахаз.","І приносив він жертви богам дамаським, думаючи, що вони вражали його, і говорив: боги царів сирійських допомагають їм; принесу я жертву їм, і вони допоможуть мені. Але вони були на падіння йому і всьому Ізраїлю.","І зібрав Ахаз сосуди дому Божого, і розтрощив сосуди дому Божого, і замкнув двері дому Господнього, і спорудив собі жертовники по всіх кутах в Єрусалимі,","і по всіх містах Іудиних спорудив висоти для кадіння богам іншим, і гнівив Господа Бога батьків своїх.","Інші діла його й усі вчинки його, перші й останні, описані в книзі царів юдейських та ізраїльських.","І спочив Ахаз з батьками своїми, і поховали його в місті, в Єрусалимі, але не внесли його в гробниці царів Ізраїлевих. І став царем Єзекія, син його, замість нього."],"x":{"1":"11.16.2","2":"11.16.3","3":"4.18.9|11.14.24|38.13.1","4":"4.12.2","5":"11.16.5","9":"13.15.1-2|14.9.7","10":"2.25.42|4.15.9","13":"3.18.5|5.22.20","15":"4.15.13|4.34.3","16":"11.16.7","18":"11.18.8","19":"32.15.4|1.32.25","21":"11.16.8|32.2.36","23":"11.16.10","24":"11.16.4","26":"11.16.1","27":"11.16.20|31.14.28"}},{"v":["Єзекія став царем двадцяти п’яти років, і двадцять дев’ять років царював у Єрусалимі; ім’я матері його Авия, дочка Захарії.","І робив він угодне в очах Господніх так само, як робив Давид, батько його.","У перший же рік царювання свого, у перший місяць, він відчинив двері дому Господнього і відновив їх,","і повелів прийти священикам і левитам, і зібрав їх на площі східній,","і сказав їм: послухайте мене, левити! Нині освятіться самі й освятіть дім Господа Бога батьків ваших, і викиньте нечистоту зі святилища.","Тому що батьки наші чинили беззаконно, і робили неугодне в очах Господа Бога нашого, і залишили Його, і відвернули вони лиця свої від оселі Господньої, і повернулися спиною,","і замкнули двері притвору, і погасили світильники, і не палили куріння, і не відносили всепалень у святилищі Бога Ізраїлевого.","І був гнів Господа на Юдею і на Єрусалим, і Він віддав їх на ганьбу, на спустошення і на посміх, як ви бачите очима вашими.","І ось, упали батьки наші від меча, а сини наші і дочки наші і дружини наші за це в полоні [в землі не своїй] донині.","Тепер у мене на серці — укласти завіт з Господом Богом Ізраїлевим, нехай відверне від нас полум’я гніву Свого.","Діти мої! не будьте недбалі, тому що вас обрав Господь стояти перед лицем Його, служити Йому і бути в Нього служителями і запалювачами курінь.","І встали левити: Махаф, син Амасая, й Іоель, син Азарії, із синів Каафових; і з синів Мерариних: Кис, син Авдія, й Азарія, син Ієгаллелела; і з племені Гирсонового: Іоах, син Зимми, й Еден, син Іоаха;","і з синів Елицафанових: Шимри та Ієіел; і з синів Асафових: Захарія і Матфанія;","і з синів Еманових: Ієхиїл і Шимей; і з синів Ідифунових: Шемаія й Уззиел.","Вони зібрали братів своїх і освятилися, і пішли за наказом царя очищати дім Господній за словами Господа.","І ввійшли священики всередину дому Господнього для очищення, і винесли все нечисте, що знайшли в храмі Господньому, на двір дому Господнього, а левити взяли це, щоб винести геть до потоку Кедрона.","І почали освячувати в перший день першого місяця, і у восьмий день того самого місяця ввійшли в притвор Господній; і освячували дім Господній вісім днів, і в шістнадцятий день першого місяця закінчили.","І прийшли в дім до царя Єзекії і сказали: ми очистили дім Господній, і жертовник для всепалення, і всі сосуди його, і стіл для хлібів предкладення, і всі сосуди його;","і всі сосуди, які закинув цар Ахаз під час царювання свого, у беззаконні своєму, ми приготували й освятили, і ось вони перед жертовником Господнім.","І встав цар Єзекія рано-вранці і зібрав начальників міста, і пішов у дім Господній.","І привели сім тельців і сім баранів, і сім агнців і сім козлів у жертву за гріх за царство і за святилище і за Юдею; і наказав він синам Аароновим, священикам, вознести всепалення на жертовнику Господньому.","І закололи тельців, і взяли священики кров, і окропили жертовник, і закололи баранів, і окропили кров’ю жертовник; і закололи агнців, і окропили кров’ю жертовник.","І привели козлів за гріх перед лице царя і зібрання, і вони поклали руки свої на них.","І закололи їх священики, і очистили кров’ю їх жертовник для загладження гріхів усього Ізраїля, тому що за весь Ізраїль наказав цар принести всепалення і жертву за гріх.","І поставив він левитів у домі Господньому з кимвалами, псалтирями і цитрами, за уставом Давида і Гада, прозорливця царевого, і Нафана пророка, тому що від Господа був устав цей через пророків Його.","І стали левити з музичними інструментами Давидовими і священики з трубами.","І наказав Єзекія вознести всепалення на жертовнику. І в той час, як почалося всепалення, почався спів Господу, при звуках труб та інструментів Давида, царя Ізраїлевого.","І все зібрання молилося, і співці співали, і сурмили труби, доки не закінчилося всепалення.","Після закінчення ж всепалення цар і всі, що знаходилися при ньому, схилилися і поклонилися.","І сказав цар Єзекія і князі левитам, щоб вони славили Господа словами Давида й Асафа прозорливця, і вони славили з радістю, і схилялися і поклонялися.","І продовжив Єзекія і сказав: тепер ви посвятили себе Господу; приступайте і приносьте жертви і вдячні приношення в дім Господній. І понесло все зібрання жертви і вдячні приношення, і всякий, хто розчулений був серцем, — усепалень.","І було число всепалень, які привели ті, що зібралися: сімдесят волів, сто баранів, двісті агнців — усе це для всепалення Господу.","Інших священних жертв було: шістсот з великої худоби і три тисячі з дрібної худоби.","Але священиків було мало, і вони не могли здирати шкір з усіх всепалень, і допомагали їм брати їхні левити, до закінчення справи і доки освятилися інші священики, тому що левити були більш ретельні в освяченні себе, ніж священики.","Притому ж усепалень було багато з жиром мирних жертв і з узливаннями при всепаленні. Так було відновлено служіння в домі Господньому.","І радів Єзекія і весь народ за те, що Бог так розчулив народ, бо це сталося несподівано."],"x":{"1":"11.18.2","2":"11.18.3","3":"13.28.24","5":"17.12.30","6":"10.8.48|32.2.27|36.20.16","7":"3.28.6","8":"4.28.25|10.9.8|32.51.37","11":"4.10.8","12":"12.6.44","15":"1.19.10","17":"11.23.12","19":"13.28.24","21":"2.4.13-14","22":"2.8.15","23":"1.29.10|2.1.4","25":"12.6.31","26":"3.10.10","28":"13.23.18","31":"2.7.12","34":"13.35.11","35":"2.3.3"}},{"v":["І послав Єзекія по всій землі Ізраїльській і Юдеї, і листи писав до Єфрема і Манассії, щоб прийшли в дім Господній, в Єрусалим, для звершення пасхи Господу Богу Ізраїлевому.","І поклали на раді цар і князі його і все зібрання в Єрусалимі — звершити пасху в другий місяць,","бо не могли зробити її у свій час, тому що священики ще не освятилися в достатній кількості і народ не зібрався в Єрусалим.","І сподобалося це цареві і всьому зібранню.","І вирішили оголосити по всьому Ізраїлю, від Вирсавії до Дана, щоб ішли в Єрусалим для звершення пасхи Господу Богу Ізраїлеву, тому що давно не звершували її, як написано.","І пішли гінці з листами від царя і від князів його по всій землі Ізраїльській та Юдеї, і за повелінням царя говорили: діти Ізраїля! наверніться до Господа Бога Авраама, Ісаака й Ізраїля, і Він повернеться до залишка, який уцілів у вас від руки царів ассирійських.","І не будьте такими, як батьки ваші і брати ваші, які беззаконно чинили перед Господом Богом батьків своїх; і Він віддав їх на спустошення, як ви бачите.","Нині не будьте жорстокосердими, як батьки ваші, підкоріться Господу і приходьте до святилища Його, яке Він освятив повік; і служіть Господу Богу вашому, і Він відверне від вас полум’я гніву Свого.","Коли ви навернетеся до Господа, тоді брати ваші і діти ваші [будуть] у милості у тих, що полонили їх, і повернуться в землю цю, бо благий і милосердний Господь Бог ваш і не відверне лиця від вас, якщо ви навернетеся до Нього.","І ходили гінці з міста до міста по землі Єфремовій і Манассіїній і до Завулонової, але з них сміялися і знущалися.","Однак деякі з коліна Асирового, Манассіїного і Завулонового смирилися і прийшли в Єрусалим.","І над Юдеєю була рука Божа, яка дарувала їм єдине серце, щоб виконувати повеління царя і князів, за словом Господнім.","І зібралося в Єрусалим безліч народу для звершення свята опрісноків, у другий місяць, — зібрання дуже численне.","І встали і зруйнували жертовники, які були в Єрусалимі; і все, на чому звершувалося куріння [ідолам], зруйнували і кинули в потік Кедрон;","і закололи пасхального агнця в чотирнадцятий день другого місяця. Священики і левити присоромившись, освятилися і принесли всепалення в дім Господній,","і стали на своєму місці за уставом своїм, за законом Мойсея, чоловіка Божого. Священики кропили кров’ю [приймаючи її] з рук левитів.","Оскільки багато було в зібранні таких, які не освятилися, то замість нечистих левити закололи пасхального агнця, для присвяти Господу.","Багато хто з народу, більшість з коліна Єфремового і Манассіїного, Іссахарового і Завулонового, не очистилися; однак вони їли пасху, не за уставом.","Але Єзекія помолився за них, говорячи: Господь благий нехай простить кожного, хто розчулив серце своє до того, щоб шукати Господа Бога, Бога батьків своїх, хоча і без очищення священного!","І почув Господь Єзекію і простив народ.","І звершили сини Ізраїлеві, які знаходилися в Єрусалимі, свято опрісноків за сім днів, з великою радістю; щодня левити і священики славили Господа на інструментах, зроблених для славослів’я Господа.","І говорив Єзекія за серцем усім левитам, які мали добре розуміння в служінні Господу. І їли святкове сім днів, приносячи жертви мирні і славлячи Господа Бога батьків своїх.","І вирішило все зібрання святкувати інші сім днів, і провели ці сім днів у веселощах,","тому що Єзекія, цар Юдейський, виставив для тих, що зібралися, тисячу тельців і десять тисяч дрібної худоби, і вельможі виставили для тих, що зібралися, тисячу тельців і десять тисяч дрібної худоби; і священиків освятилося вже багато.","І веселилися всі ті, що зібралися з Юдеї, і священики і левити, і все зібрання, яке прийшло від Ізраїля, і прибульці, які прийшли з землі Ізраїльської і жили в Юдеї.","І була радість велика в Єрусалимі, тому що з днів Соломона, сина Давидового, царя Ізраїлевого, не бувало подібного до цього в Єрусалимі.","І встали священики і левити, і благословили народ; і почутий був голос їх, і зійшла молитва їх у святу оселю Його на небеса."],"x":{"1":"1.12.11:18|2.23.5|2.23.21","2":"1.12.6|1.13.4|3.9.11","5":"1.12.3","6":"1.3.6|1.4.5|11.15.19","7":"13.29.8|1.32.8|32.13.16|52.17.18","9":"1.34.6|32.3.12","12":"54.4.32|54.11.21|32.32.39","13":"53.11.55","15":"3.9.11:21","18":"3.9.6|1.12.3|2.22.4","25":"1.12.43:48","27":"3.6.23:27"}},{"v":["І після закінчення всього цього, пішли всі ізраїльтяни, які там знаходилися, в міста юдейські і розбили статуї, зрубали освячені дерева, і зруйнували висоти і жертовники по всій Юдеї і в землі Веніаміновій, Єфремовій і Манассіїній, до кінця. І потім повернулися всі сини Ізраїлеві, кожен у володіння своє, в міста свої.","І поставив Єзекія черги священиків і левитів, за їхнім розподілом, кожного при своїй справі, священичій або левитській, при всепаленні і при жертвах мирних, для служби, для хваління і славослів’я, біля воріт дому Господнього.","І визначив цар частину з майна свого на всепалення: на всепалення ранкові і вечірні, і на всепалення в суботи і в новомісяччя, й у свята, як написано в законі Господньому.","І повелів він народу, який живе в Єрусалимі, давати визначене утримання священикам і левитам, щоб вони були ревні в законі Господньому.","Коли обнародувано було це повеління, тоді нанесли сини Ізраїлеві багато початків хліба, вина, й олії, і меду, і всяких плодів польових; і десятин з усього нанесли багато.","І ізраїльтяни і юдеї, які живуть у містах юдейських, також представили десятини з великої і дрібної худоби і десятини з пожертвувань, присвячених Господу Богу їхньому; і наклали купи, купи.","У третій місяць почали класти купи, і в сьомий місяць закінчили.","І прийшли Єзекія і вельможі, і побачили купи, і дякували Господу і народу Його Ізраїлю.","І запитав Єзекія священиків і левитів про ці купи.","І відповів йому Азарія первосвященик з дому Садокового і сказав: з того часу, як почали носити приношення в дім Господній, ми їли досита, і багато чого залишилося, тому що Господь благословив народ Свій. Із того, що залишилося, склалася така безліч.","І наказав Єзекія приготувати кімнати при домі Господньому. І приготували.","І перенесли туди приношення, і десятини, і пожертвування, з усією ретельністю. І був начальником при них Хонанія левит, і Симей, брат його, другим.","А Ієхиїл і Азазія, і Нахаф, і Асаїл, і Ієримоф, й Іозавад, і Елиел, і Ісмахія, і Махаф, і Бенанія були доглядачами під рукою Хонанії і Симея, брата його, за наказом царя Єзекії й Азарії, начальника при домі Божому.","Коре, син Імни, левит, воротар на східній стороні, був при добровільних приношеннях Богу, для видачі принесеного Господу і найважливіших з присвячених речей.","І під його віданням знаходилися Еден, і Миніамін, й Ієшуа, і Шемаія, і Амарія, і Шеханія в містах священичих, щоб правильно роздавати братам своїм частини, як великому, так і малому,","зверх списків їх, усім чоловічої статі від трьох років і вище, усім, хто ходить у дім Господа для справ щоденних, для служіння їх, за посадами їх і за відділами їх,","і внесеним у список священикам, за поколіннями їх, і левитам від двадцяти років і вище, за посадами їх, за відділами їх,","і внесеним у список, з усіма малолітніми їхніми, з дружинами їхніми і з синами їхніми і з дочками їхніми, — всій громаді, тому що вони з усією вірністю присвятили себе на священну службу.","І для синів Ааронових, священиків у селищах навколо міст їх, при кожному місті поставлені були мужі пойменовані, щоб роздавати ділянки всім чоловічої статі у священиків і усім, внесеним у список у левитів.","Ось що зробив Єзекія по всій Юдеї, — і він робив добре, і справедливе, й істинне перед лицем Господа Бога свого.","І в усьому, що він здійснював для служіння дому Божому і для дотримання закону і заповідей, думаючи про Бога свого, він діяв від усього серця свого і мав успіх."],"x":{"1":"11.18.4|4.7.5","2":"12.24.19","3":"3.28.2-3","4":"3.18.8|17.13.10","5":"1.23.19|1.34.26|2.2.14","6":"3.31.28","14":"2.2.3|3.18.9","20":"11.18.3:5","21":"11.18.6|13.26.5"}},{"v":["Після таких діл і вірности, прийшов Сеннахирим, цар Ассирійський, і вступив у Юдею, і обложив укріплені міста, і думав відторгнути їх собі.","Коли Єзекія побачив, що прийшов Сеннахирим з наміром воювати проти Єрусалима,","тоді вирішив із князями своїми і з військовими людьми своїми засипати джерела води, що поза містом, і ті допомогли йому.","І зібралося багато народу, і засипали всі джерела і потік, що протікав по країні, говорячи: нехай не знайдуть царі ассирійські, прийшовши сюди, багато води [і нехай не укріпляться].","І підбадьорився він, і відновив усю стіну, що обвалилася, і підняв її до вежі, і ззовні побудував іншу стіну, і укріпив Милло в місті Давидовому, і приготував багато зброї і щитів.","І поставив воєначальників над народом, і зібрав їх до себе на площу біля міських воріт, і говорив до серця їх, і сказав:","будьте твердими і мужніми, не бійтеся і не страшіться царя Ассирійського і всієї безлічі, яка з ним, тому що з нами більше, ніж з ним;","з ним м’язи плотські, а з нами Господь Бог наш, щоб допомагати нам і боротися у битвах наших. І укріпився народ словами Єзекії, царя Юдейського.","Після цього послав Сеннахирим, цар Ассирійський, рабів своїх в Єрусалим, — сам він стояв навпроти Лахиса, і вся сила його з ним, — до Єзекії, царя Юдейського, і до всіх юдеїв, які в Єрусалимі, сказати:","так говорить Сеннахирим, цар Ассирійський: на що ви сподіваєтеся і сидите в фортеці в Єрусалимі?","Чи не зваблює вас Єзекія, щоб віддати вас на смерть від голоду і спраги, говорячи: Господь Бог наш врятує нас від руки царя Ассирійського?","чи не цей Єзекія зруйнував висоти Його і жертовники Його, і сказав Юдеї та Єрусалиму: перед жертовником єдиним поклоняйтеся і на ньому звершуйте куріння?","Хіба ви не знаєте, що зробив я і батьки мої з усіма народами земель? Чи могли боги народів земних урятувати землю свою від руки моєї?","Хто з усіх богів народів, знищених батьками моїми, міг врятувати народ свій від руки моєї? Як же зможе ваш Бог врятувати вас від руки моєї?","І нині нехай не зваблює вас Єзекія і не відхиляє вас у такий спосіб; не вірте йому: якщо не в силах був жоден бог жодного народу і царства врятувати народ свій від руки моєї і від руки батьків моїх, то і ваш Бог не врятує вас від руки моєї.","І ще багато чого говорили раби його проти Господа Бога і проти Єзекії, раба Його.","І листи писав він, у яких ганьбив Господа Бога Ізраїлевого і говорив проти Нього такі слова: як боги народів земних не врятували народів своїх від руки моєї, так Бог Єзекії не врятує народу Свого від руки моєї.","І кричали гучним голосом юдейською мовою до народу єрусалимського, який був на стіні, щоб устрашити його і налякати його, і взяти місто.","І говорили про Бога Єрусалима, як про богів народів землі, — вироби рук людських.","І помолився цар Єзекія й Ісая, син Амосів, пророк, і воззвали до неба.","І послав Господь ангела, і він знищив усіх хоробрих і головнокомандувача і начальників у війську царя Ассирійського. І повернувся він зі соромом у землю свою; і коли прийшов у дім бога свого, — ті, що вийшли зі стегон його, вразили його там мечем.","Так врятував Господь Єзекію і жителів Єрусалима від руки Сеннахирима, царя Ассирійського, і від руки всіх і оберігав їх звідусюди.","Тоді багато хто приносив дари Господу в Єрусалим і коштовні речі Єзекії, царю Юдейському. І він звеличився після цього в очах усіх народів.","У ті дні занедужав Єзекія смертельно. І помолився Господу, і Він почув його і дав йому знамення.","Але не воздав Єзекія за зроблені йому благодіяння, тому що загордилося серце його. І був на нього гнів Божий і на Юдею, і на Єрусалим.","Але оскільки смирився Єзекія в гордості серця свого, — сам і жителі Єрусалима, то не прийшов на них гнів Господній у дні Єзекії.","І було в Єзекії багатства і слави дуже багато, і сховище він зробив у себе для срібла і золота, і каменів коштовних, і для пахощів і щитів, і для всяких коштовних сосудів;","і комори для плодів землі, для хліба, вина й олії, і стійла для всякого роду худоби, і двори для стад.","І міста побудував собі. І стад дрібної і великої худоби було в нього безліч, тому що дав йому Бог дуже велике майно.","Він же, Єзекія, замкнув верхню протоку вод Геона і провів їх униз до західної сторони міста Давидового. І діяв успішно Єзекія в усякій справі своїй.","Тільки при послах царів вавилонських, які надсилали до нього запитати про знамення, що було на землі, залишив його Бог, щоб випробувати його і відкрити все, що у нього на серці.","Інші діяння Єзекії і чесноти його описані у видінні Ісаї, сина Амосового, пророка, і в книзі царів юдейських та ізраїльських.","І спочив Єзекія з батьками своїми, і поховали його над гробницями синів Давидових, і почесті віддали йому після смерти його всі юдеї і жителі Єрусалима. І став царем Манассія, син його, замість нього."],"x":{"1":"11.18.13|30.48.20|31.36.1","5":"13.25.23","7":"11.6.16|58.4.4|31.31.3","9":"11.18.17|43.1.13","10":"11.18.19","11":"11.18.29","12":"11.18.22","13":"11.18.33-34|31.10.9","14":"4.2.34|11.18.35","17":"11.19.14|31.37.10:14","18":"11.18.26:28","19":"11.18.33","20":"11.19.1:14","21":"11.19.35|31.37.36","24":"11.20.1|30.48.26|31.38.1","25":"52.17.18|31.39.2","26":"11.20.17-18","30":"11.20.20","31":"31.39.1|11.20.11|4.8.2|4.13.3","32":"31.36.1|11.18.1","33":"11.20.21"}},{"v":["Дванадцяти років був Манассія, коли став царем, і п’ятдесят п’ять років царював у Єрусалимі,","і чинив він неугодне в очах Господніх, наслідуючи мерзоти народів, яких прогнав Господь від лиця синів Ізраїлевих,","і знову побудував висоти, які зруйнував Єзекія, батько його, і поставив жертовники Ваалам, і влаштував діброви, і поклонявся всьому воїнству небесному, і служив йому,","і спорудив жертовники в домі Господньому, про який сказав Господь: в Єрусалимі буде ім’я Моє вічно;","і спорудив жертовники всьому воїнству небесному на обох дворах дому Господнього.","Він же проводив синів своїх через вогонь у долині сина Енномового, і ворожив, і чаклував, і запровадив викликателів мерців і чародіїв; багато робив він неугодного в очах Господа, щоб прогнівати Його.","І поставив різьбленого ідола, якого зробив, у домі Божому, про який говорив Бог Давиду і Соломону, синові його: у домі цьому і в Єрусалимі, який Я обрав з усіх колін Ізраїлевих, Я покладу ім’я Моє повік;","і не дам надалі виступити нозі Ізраїля із землі цієї, яку Я затвердив за батьками їх, якщо тільки вони будуть намагатися виконувати все, що Я заповів їм, за всім законом і уставами і повеліннями, даними рукою Мойсея.","Але Манассія довів Юдею і жителів Єрусалима до того, що вони чинили гірше за ті народи, які знищив Господь від лиця синів Ізраїлевих.","І говорив Господь до Манассії і до народу його, але вони не слухали.","І привів Господь на них воєначальників царя Ассирійського, і закували вони Манассію в кайдани й зв’язали його ланцюгами, і відвели його у Вавилон.","І в тісноті своїй він став благати лице Господа Бога свого і глибоко смирився перед Богом батьків своїх.","І помолився Йому, і Бог прихилився до нього і почув моління його, і повернув його в Єрусалим у царство його. І пізнав Манассія, що Господь є Бог.","І після того побудував зовнішню стіну міста Давидового, на західній стороні Геона, по долині і до входу в Рибні ворота, і провів її навколо Офела і високо підняв її. І поставив воєначальників по всіх укріплених містах в Юдеї,","і скинув чужоземних богів та ідола з дому Господнього, і всі капища, які спорудив на горі дому Господнього в Єрусалимі, і викинув їх за місто.","І відновив жертовник Господній і приніс на ньому жертви мирні й хвалебні, і сказав юдеям, щоб вони служили Господу Богу Ізраїлевому.","Але народ ще приносив жертви на висотах, хоч і Господу Богу своєму.","Інші діла Манассії, і молитва його до Бога свого, і слова прозорливців, які говорили до нього ім’ям Господа Бога Ізраїлевого, знаходяться в записах царів ізраїлевих.","І молитва його, і те, що Бог прихилився до нього, і всі гріхи його і беззаконня його, і місця, на яких він побудував висоти і поставив зображення Астарти й ідолів, раніше ніж смирився, описані в записах Хозая.","І спочив Манассія з батьками своїми, і поховали його в домі його. І став царем Амон, син його, замість нього.","Двадцяти двох років був Амон, коли став царем, і два роки царював у Єрусалимі.","І чинив неугодне в очах Господніх так, як робив Манассія, батько його; і всім ідолам, яких зробив Манассія, батько його, приносив Амон жертви і служив їм.","І не смирився перед лицем Господнім, як смирився Манассія, батько його; навпаки, Амон примножив свої гріхи.","І склали проти нього змову слуги його, й умертвили його в домі його.","Але народ землі перебив усіх, хто був у змові проти царя Амона, і поставив народ царем землі Іосію, сина його, замість нього."],"x":{"1":"11.21.1","2":"4.18.9","3":"11.21.3|1.34.13|54.7.42","4":"4.12.11|10.8.29|32.32.34","5":"4.4.19","6":"2.18.21|2.19.26|2.20.2","7":"11.21.7","8":"9.7.10|10.8.16|11.21.8","9":"11.21.9","13":"37.4.33","14":"17.3.3:26|13.27.3","18":"11.21.16-17","20":"11.21.18","25":"11.21.24"}},{"v":["Вісім років було Іосії, коли він став царем, і тридцять один рік царював у Єрусалимі,","і робив він угодне в очах Господніх, і ходив путями Давида, батька свого, і не ухилявся ні праворуч, ні ліворуч.","У восьмий рік царювання свого, будучи ще отроком, він почав удаватися до Бога Давида, батька свого, а в дванадцятий рік почав очищати Юдею та Єрусалим від висот і посвячених дерев і від різьблених і відлитих ідолів.","І зруйнували перед лицем його жертовники Ваала і статуї, що піднімалися над ними; і посвячені дерева він зрубав, і різьблені і відлиті кумири зламав і розбив на порох, і розсипав на гробах тих, які приносили їм жертви,","і кістки жерців спалив на жертовниках їхніх, і очистив Юдею та Єрусалим,","і в містах Манассії, та Єфрема, і Симеона, навіть до коліна Неффалимового, і в спустошених околицях їх","він зруйнував жертовники і посвячені дерева, й ідолів розбив на порох, і всі статуї розтрощив по всій землі Ізраїльській, і повернувся в Єрусалим.","У вісімнадцятий рік царювання свого, після очищення землі і дому Божого, він послав Шафана, сина Ацалії, і Маасею градоначальника, й Іоаха, сина Іоахазового, писаря, відновити дім Господа Бога свого.","І прийшли вони до Хелкії первосвященика, і віддали срібло, принесене в дім Божий, яке левити, що стоять на варті біля порогу, зібрали з рук Манассії й Єфрема і всіх інших ізраїльтян, і від усього Іуди і Веніаміна, і від жителів Єрусалима,","і віддали в руки виконавцям робіт, які були приставлені до дому Господнього, щоб вони роздавали його робітникам, які працювали в домі Господньому, на відбудові й оновленні дому.","І вони роздавали теслям і будівельникам на купівлю тесаних каменів і дерев для зв’язків і для покриття будинків, які зруйнували царі юдейські.","Люди ці діяли чесно під час роботи, і для нагляду над ними поставлені були Іахаф і Овадія, левити із синів Мерариних, і Захарія і Мешуллам із синів Каафових, і всі левити, що вміють грати на музичних інструментах.","Вони ж були приставниками над носіями і наглядали за усіма робітниками при кожній роботі; з левитів же були і писарі, і наглядачі, і воротарі.","Коли виймали вони срібло; принесене в дім Господній, тоді Хелкія священик знайшов книгу закону Господнього, дану рукою Мойсея.","І почав Хелкія, і сказав Шафану писарю: книгу закону знайшов я в домі Господньому. І подав Хелкія ту книгу Шафану.","І поніс Шафан книгу до царя, і приніс при цьому цареві звістку: все, що доручено рабам твоїм, вони роблять;","і висипали срібло, знайдене в домі Господньому, і передали його в руки приставників і в руки виконавців робіт.","І також доніс Шафан писар царю, говорячи: книгу дав мені Хелкія священик. І читав її Шафан перед царем.","Коли почув цар слова закону, то роздер одяг свій.","І дав цар повеління Хелкії й Ахикаму, синові Шафановому, й Авдону, синові Михея, і Шафану писарю, й Асаії, слузі царському, говорячи:","підіть, запитайте Господа про мене і про тих, що залишились у Ізраїля, і про Іуду щодо слів цієї знайденої книги, тому що великий гнів Господа, який запалав на нас за те, що не дотримувалися батьки наші слова Господнього, щоб чинити за всім написаним у книзі цій.","І пішов Хелкія і ті, які від царя, до Олдани пророчиці, дружини Шаллума, сина Тавкегафа, сина Хасри, хранителя одягу, — а жила вона в другій частині Єрусалима, — і говорили з нею про це.","І вона сказала їм: так говорить Господь Бог Ізраїлів: скажіть тому чоловікові, який послав вас до мене:","так говорить Господь: ось Я наведу лихо на місце це і на жителів його всі прокляття, написані в книзі, яку читали перед лицем царя Юдейського,","за те, що вони залишили Мене і кадили богам іншим, щоб прогнівляти Мене всіма ділами рук своїх. І гнів Мій запалає над місцем цим і не згасне.","А царю Юдейському, який послав вас запитати Господа, так скажіть: так говорить Господь Бог Ізраїлів про слова, які ти чув:","оскільки пом’якшало серце твоє, і ти смирився перед Богом, почувши слова Його про місце це і про жителів його, — і ти смирився переді Мною, і роздер одяг свій, і плакав переді Мною, то і Я почув тебе, говорить Господь.","Ось Я преставлю тебе до батьків твоїх, і покладений будеш у гробницю твою в мирі, і не побачать очі твої всього того лиха, яке Я наведу на місце це і на жителів його. І принесли цареві відповідь.","І послав цар, і зібрав усіх старійшин Юдеї та Єрусалима, і пішов цар у дім Господній,","і з ним усі юдеї і жителі Єрусалима, і священики і левити, і весь народ, від великого до малого; і він прочитав уголос їм усі слова книги завіту, знайденої в домі Господньому.","І став цар на місці своєму, й уклав завіт перед лицем Господа йти за Господом і дотримуватися заповіді Його й одкровення Його, й уставів Його, від усього серця свого і від усієї душі своєї, щоб виконувати слова завіту, написані в книзі цій.","І повелів цар підтвердити це всім, хто знаходився в Єрусалимі й у землі Веніаміновій; і стали чинити жителі Єрусалима за завітом Бога, Бога батьків своїх.","І викинув Іосія всі мерзоти з усіх земель, які у синів Ізраїлевих, і звелів усім, хто знаходився у землі Ізраїлевій, служити Господу Богу своєму. І в усі дні життя його вони не відступали від Господа Бога батьків своїх."],"x":{"1":"11.22.1","2":"11.22.2|4.5.32","4":"2.26.30","5":"11.23.8","8":"11.22.3","9":"11.22.4","12":"11.12.15","14":"11.22.8","16":"11.22.9","19":"2.26.14|4.28.15","24":"2.26.14:16|4.28.15","26":"11.22.18","27":"4.20.3","28":"32.34.4|11.22.20","30":"11.23.2","31":"11.23.3","33":"11.23.4"}},{"v":["І звершив Іосія в Єрусалимі пасху Господу, і закололи пасхального агнця в чотирнадцятий день першого місяця.","І поставив він священиків на місцях їхніх, і підбадьорював їх на служіння в домі Господньому,","і сказав левитам, наставникам усіх ізраїльтян, посвяченим Господу: поставте ковчег святий у храмі, який побудував Соломон, син Давидів, цар Ізраїлів; немає вам потреби носити його на раменах; служіть тепер Господу Богу нашому і народу Його Ізраїлю;","станьте за поколіннями вашими, за чергами вашими, як запропоновано Давидом, царем Ізраїлевим, і як приписано Соломоном, сином його,","і стійте у святилищі, за розподілом поколінь між братами вашими, синами народу, і за розподілом поколінь серед левитів,","і заколіть пасхального агнця, й освятіться, і приготуйте його для братів ваших, роблячи згідно зі словом Господнім через Мойсея.","І дав Іосія в дарунок синам народу, усім, що знаходилися там, із дрібної худоби агнців і козлів молодих, усе для жертви пасхальної, числом тридцять тисяч і три тисячі волів. Це з майна царя.","І князі його від щирости давали в дарунок народу, священикам і левитам: Хелкія і Захарія та Ієхиїл, начальники в домі Божому, дали священикам для жертви пасхальної дві тисячі шістсот [овець, агнців і козлів] і триста волів;","і Хонанія, і Шемаія, і Нафанаїл, брати його, і Хашавія, та Ієиел, й Іозавад, начальники левитів, подарували левитам для жертви пасхальної [овець] п’ять тисяч і п’ятсот волів.","Так влаштовано було служіння. І стали священики на місце своє і левити за чергами своїми, за велінням царським;","і закололи пасхального агнця. І кропили священики кров’ю, приймаючи її з рук левитів, а левити знімали шкуру;","і розподілили призначене для всепалення, щоб роздати те по відділеннях поколінь серед синів народу, для приношення Господу, як написано в книзі Мойсеєвій. Те саме зробили і з волами.","І спекли пасхального агнця на вогні, за уставом; і священні жертви зварили в казанах, горщиках і каструлях, і поспішно роздали всьому народові,","а потім приготували для себе і для священиків, тому що священики, сини Ааронові, зайняті були приношенням всепалення і жиру до ночі; через це і готували левити для себе і для священиків, синів Ааронових.","І співці, сини Асафові, залишалися на місцях своїх, за встановленням Давида й Асафа, й Емана й Ідифуна, прозорливця царського, і воротарі біля кожних воріт: не треба було їм відходити від служіння свого, тому що брати їхні левити готували для них.","Так влаштовано було все служіння Господу в той день, щоб звершити пасху і принести всепалення на жертовнику Господньому, за велінням царя Іосії.","І звершували сини Ізраїлеві, які знаходилися там, пасху в той час і свято опрісноків протягом семи днів.","І не звершувалася така пасха в Ізраїлі від днів Самуїла пророка; і з усіх царів Ізраїлевих жоден не звершував такої пасхи, яку звершив Іосія, і священики, і левити, і всі юдеї, й ізраїльтяни, які там знаходилися, і жителі Єрусалима.","У вісімнадцятий рік царювання Іосії звершена ця пасха.","Після всього того, що зробив Іосія в домі Божому [і як спалив вогнем цар Іосія і черевомовців, і волхвів, і капища, й ідолів, і діброви, що були в Єрусалимі та Юдеї, щоб утвердити слова закону, написані в книзі, яку знайшов Хелкія священик у домі Господньому, не було подібного до нього раніше нього, хто звернувся б до Господа всім серцем своїм, і всією душею своєю, і всією кріпкістю своєю, за всім законом Мойсеєвим; не постав і після нього подібний до нього. Однак же не відвернувся Господь від великої люті гніву Свого, — люті, якою розгнівався Господь на Юдею за всі образи, якими прогнівив Манассія. І сказав Господь: і Іуду відкину від лиця Мого, як відкинув дім Ізраїлів, і відкину місто Єрусалим, яке обрав, і храм, про який сказав: буде там ім’я Моє,] пішов Нехао, цар Єгипетський, на війну до Кархемиса на Євфраті; й Іосія вийшов назустріч йому.","І послав до нього Нехао послів сказати: що мені і тобі, царю Юдейський? Не проти тебе тепер іду я, але туди, де у мене війна. І Бог повелів мені поспішати; не протився Богу, Який зі мною, щоб Він не погубив тебе.","Але Іосія не відсторонився від нього, а приготувався, щоб воювати з ним, і не послухав слів Нехао від лиця Божого і виступив на битву на рівнину Мегиддо.","І вистрілили стрільці в царя Іосію, і сказав цар слугам своїм: відведіть мене, бо я тяжко поранений.","І звели його слуги його з колісниці, і посадили його в інший візок, який був у нього, і відвезли його в Єрусалим. І помер він, і похований у гробницях батьків своїх. І вся Юдея та Єрусалим оплакали Іосію.","Оплакав Іосію і Єремія в пісні жалісній; і говорили всі співці і співачки про Іосію в жалісних піснях своїх, відомих до цього дня, і передали їх для вживання в Ізраїля; і ось вони вписані у книгу жалісних пісень.","Інші діяння Іосії і чесноти його, відповідні приписам закону Господнього,","і діяння його, перші й останні, описані в книзі царів ізраїльських і юдейських."],"x":{"1":"11.23.21|15.1.1","3":"10.6.1","6":"1.12.3","7":"3.28.19","8":"2.7.16","13":"1.12.8|4.16.7","15":"12.25.1","17":"1.12.15","18":"11.23.22","19":"11.23.23","20":"11.23.24-25","22":"48.12.11","23":"11.23.29","24":"11.23.30","25":"32.22.10","26":"11.22.1"}},{"v":["І взяв народ землі Іоахаза, сина Іосіїного, [і помазали його] і поставили його царем, замість батька його, в Єрусалимі.","Двадцяти трьох років був Іоахаз, коли став царем, і три місяці царював у Єрусалимі. [Ім’я матері його — Амитал, дочка Єремії з Ловни. І зробив він лукаве перед Господом у всьому, що зробили батьки його. І закував його фараон Нехао в Девлафі, в землі Емафській, щоб не царювати йому в Єрусалимі.]","І скинув його цар Єгипетський в Єрусалимі [і привів його цар у Єгипет], і наклав на землю пені сто талантів срібла і талант золота.","І поставив цар Єгипетський над Юдеєю та Єрусалимом Єлиакима, брата його, і перемінив ім’я його на Іоакима, а Іоахаза, брата його, взяв Нехао і відвів його в Єгипет [і він помер там. І срібло і золото давав фараонові: тоді земля почала давати срібло за словом фараона, і кожен, за владою, вимагав срібла і золота від народу землі для данини фараонові Нехао].","Двадцяти п’яти років був Іоаким, коли став царем, і одинадцять років царював у Єрусалимі [ім’я матері його Зехора, дочка Нириєва з Рами]. І робив він неугодне в очах Господа Бога свого [в усьому, що робили батьки його. У дні його прийшов Навуходоносор, цар Вавилонський, на землю, і він служив йому три роки і відступив від нього. І послав Господь на них халдеїв і розбійників сирських, і розбійників моавитських, і синів Аммонових і самарійських, і відступили за словом цим, — за словом Господа вустами рабів Його, пророків. Утім, гнів Господа був на Іуді, щоб відкинути його від лиця Його, за всі гріхи Манассії, які він зробив, і за кров невинну, яку пролив Іоаким і наповнив Єрусалим невинною кров’ю. Але не захотів Господь викорінити їх].","Проти нього вийшов Навуходоносор, цар Вавилонський, і закував його в кайдани, щоб відвести його у Вавилон.","І частину сосудів дому Господнього переніс Навуходоносор у Вавилон і поклав їх у капищі своєму у Вавилоні.","Інші справи Іоакима і мерзоти його, які він робив і які знайдені у ньому, описані в книзі царів ізраїльських і юдейських. [І спочив Іоаким з батьками своїми, і похований був у Ганозані з батьками своїми.] І став царем Ієхонія, син його, замість нього.","Вісімнадцяти років був Ієхонія, коли став царем, і три місяці і десять днів царював у Єрусалимі, і робив він неугодне в очах Господніх.","Через рік послав цар Навуходоносор і повелів взяти його у Вавилон разом з коштовними сосудами дому Господнього, і поставив царем над Юдеєю та Єрусалимом Седекію, брата його.","Двадцяти одного року був Седекія, коли став царем, і одинадцять років царював у Єрусалимі,","і робив він неугодне в очах Господа Бога свого. Він не смирився перед Єремією пророком, який пророкував від уст Господніх,","і відійшов від царя Навуходоносора, який взяв клятву з нього ім’ям Бога, — і зробив твердою шию свою й озлобив серце своє до того, що не навернувся до Господа Бога Ізраїлевого.","Та й усі начальники над священиками і над народом багато грішили, наслідуючи всі мерзоти язичників, і осквернили дім Господа, який Він освятив у Єрусалимі.","І посилав до них Господь Бог батьків їхніх, посланців Своїх від раннього ранку, бо Він жалів Свій народ і Свою оселю.","Але вони знущалися з посланого від Бога і зневажали слова Його, і ганьбили пророків Його, доки не зійшов гнів Господа на народ Його, так що не було йому порятунку.","І Він навів на них царя Халдейського, — і той умертвив юнаків їхніх мечем у домі святині їх і не пощадив [ні Седекії,] ні юнака, ні дівчини, ні старця, ні сивоволосого: все віддав Бог у руку його.","І всі сосуди дому Божого, великі і малі, і скарби дому Господнього, і скарби царя і князів його, усе приніс він у Вавилон.","І спалили дім Божий, і зруйнували стіну Єрусалима, і всі палаци його спалили вогнем, і всі коштовності його знищили.","І переселив він тих, що залишилися від меча, у Вавилон, і були вони рабами його і синів його, поки не зацарював цар Перський,","доки, на виконання слова Господнього, сказаного вустами Єремії, земля не відсвяткувала субот своїх. У всі дні запустіння вона суботствувала до виповнення сімдесяти років.","А в перший рік Кира, царя Перського, на сповнення слова Господнього, сказаного вустами Єремії, збудив Господь дух Кира, царя Перського, і він повелів оголосити по всьому царству своєму, усно і письмово, і сказати:","так говорить Кир, цар Перський: усі царства землі дав мені Господь Бог небесний, і Він повелів мені побудувати Йому дім в Єрусалимі, що в Юдеї. Хто є з вас — з усього народу Його, [нехай буде] Господь Бог його з ним, і нехай він туди йде.","МОЛИТВА МАНАССІЇ, ЦАРЯ ЮДЕЙСЬКОГО, КОЛИ ВІН УТРИМУВАВСЯ В ПОЛОНІ У ВАВИЛОНІ*\nГосподи Вседержителю, Боже отців наших, Авраама й Ісаака та Якова, і сімені їх праведного [а], що створив небо і землю з усією красою їх, що зв’язав море словом повеління Твого, що поклав безодню і запечатав її страшним і славним ім’ям Твоїм, Якого усі бояться, і тремтять від лиця сили Твоєї, тому що ніхто не може встояти перед величчю слави Твоєї, і нестерпний гнів [б] покарання Твого на грішників [в]! Але безмірна і недослідима милість обітування Твого [г], тому що Ти Господь вишній, благий, довготерпеливий і многомилостивий і каєшся про злоби людські. Ти, Господи, за множеством Твоєї благості, обіцяв покаяння [д] і відпущення тим, що згрішили перед Тобою, і множеством щедрот Твоїх визначив покаяння грішникам на спасіння. Отже, Ти, Господи, Боже праведних, не поклав покаяння праведним [е] Аврааму й Ісааку та Якову, які не згрішили перед Тобою, але поклав покаяння мені грішнику, тому що я згрішив більше за кількість піску морського [є]. Численні беззаконня мої, Господи, численні беззаконня мої, і я недостойний дивитися на висоту небесну від безлічі неправд моїх. Я зігнутий багатьма залізними кайданами [ж], так що не можу підняти голови моєї, і немає мені відпочинку, тому що прогнівив Тебе і зробив перед Тобою лихе [з]: не виконав волі Твоєї, не зберіг повелінь Твоїх, поставив мерзоти і примножив спокуси. І нині схиляю коліна серця мого, благаючи Тебе про благість [и]. Згрішив я, Господи, згрішив, і беззаконня мої я знаю, але прошу, молячись Тобі: відпусти мені, Господи, відпусти мені, і не згуби мене з беззаконнями моїми і не засуди мене в пекло. Тому що Ти Бог, Бог тих, хто кається, і на мені вияви всю благість Твою, спасши мене недостойного з великої милости Твоєї, і буду прославляти Тебе в усі дні життя мого [і], тому що Тебе славлять усі сили небесні, і Твоя слава повіки. Амінь.\n(а) Вих. 3, 6, 15–16. (б) Іов. 23, 13. (в) Пс. 129, 3. (г) Пс. 102, 17. Еф. 4, 32. (д) Єз. 18, 23, 32. (е) Мф. 9, 12–13. Лк. 15, 7. (є) Лк. 18, 13. (ж) 2 Пар. 33, 11. (з) 4 Цар. 21, 2. 2 Пар. 33, 2. (и) Еф. 3, 14. Притч. 28, 13. 1 Ін. 1, 9. (і) Пс. 6, 6. Іс. 38, 18."],"x":{"1":"11.23.30","3":"11.23.33","4":"11.23.34|50.1.13","5":"11.23.36","6":"11.24.1","7":"37.1.2","8":"11.24.5:8|32.22.24|12.3.16","9":"11.24.8","10":"11.24.15","11":"32.1.3|32.52.1","12":"32.37.2","14":"4.18.5","15":"32.25.4|37.9.10|50.21.36","16":"32.36.23|48.1.4|36.33.32","17":"11.25.1","18":"11.25.13|32.27.19:22","19":"11.25.9","20":"11.25.11","21":"32.25.11","22":"15.2.1","23":"31.44.28|31.45.1:13|37.2.38"},"n":{"24":["Перекладена з грецької; у єврейському тексті її немає."]}}];
